window.STUDY_DATA = {"title": "Hóa sinh y sinh", "course": "BF2601", "sourceFolder": "Slide 2024", "modules": [{"id": "s01", "title": "Enzym 1 · Khái niệm và tính chất", "group": "Enzym học lâm sàng", "description": "Bản chất enzym, tính đặc hiệu và vai trò trong kỹ thuật y sinh.", "sections": [{"title": "Bản chất và nơi hoạt động", "from": 8, "to": 11, "points": ["Enzym là chất xúc tác sinh học, có bản chất protein hoặc axit nucleic.", "Enzym được tổng hợp bên trong tế bào sống và có thể xúc tác phản ứng trong hoặc ngoài tế bào."]}, {"title": "Các tính chất được nhấn mạnh", "from": 12, "to": 17, "points": ["Enzym có cường lực xúc tác lớn và tính đặc hiệu cao.", "Tính đặc hiệu liên quan đến sự tương ứng không gian giữa trung tâm hoạt động và cơ chất ở trạng thái chuyển tiếp.", "Slide nêu điều kiện tác dụng thường thích hợp: 30–50 °C, pH trung tính, áp suất thường; đây là mô tả chung, không phải điều kiện của mọi enzym.", "Kỹ thuật đột biến và xáo trộn DNA có thể cải thiện độ bền, giúp enzym phù hợp với điều kiện sử dụng."]}, {"title": "Ứng dụng và hoạt độ", "from": 18, "to": 19, "points": ["Enzym có thể là chỉ thị chẩn đoán, mục tiêu của thuốc và tác nhân dùng điều trị.", "IU: lượng enzym xúc tác chuyển hóa 1 micromol cơ chất trong 1 phút ở điều kiện tiêu chuẩn.", "Katal: lượng enzym xúc tác chuyển hóa 1 mol cơ chất trong 1 giây."]}], "questions": [{"id": "s01-q001", "page": 10, "prompt": "Theo slide, enzym có bản chất nào?", "options": ["Protein hoặc axit nucleic", "Chỉ là lipid", "Chỉ là muối vô cơ", "Chỉ là gluxit"], "answer": 0, "explanation": "Slide định nghĩa enzym là chất xúc tác sinh học có bản chất protein hoặc axit nucleic."}, {"id": "s01-q002", "page": 11, "prompt": "Enzym được tổng hợp ở đâu?", "options": ["Bên trong tế bào sống", "Chỉ trong huyết tương", "Chỉ ngoài tế bào", "Chỉ trong ống nghiệm"], "answer": 0, "explanation": "Enzym được tổng hợp trong tế bào sống, dù nơi xúc tác có thể ở trong hoặc ngoài tế bào."}, {"id": "s01-q003", "page": 11, "prompt": "Phạm vi hoạt động của enzym được nêu trong slide là gì?", "options": ["Trong và ngoài tế bào", "Chỉ trong nhân", "Chỉ trong ti thể", "Chỉ ngoài tế bào"], "answer": 0, "explanation": "Nơi tổng hợp và nơi enzym thực hiện xúc tác không nhất thiết trùng nhau."}, {"id": "s01-q004", "page": 13, "prompt": "Tính đặc hiệu cao của enzym thể hiện ở điểm nào?", "options": ["Tác động vào phản ứng hoặc liên kết, nhóm chức nhất định", "Tác động như nhau lên mọi phân tử", "Luôn cần nhiệt độ rất cao", "Luôn hoạt động không cần cơ chất"], "answer": 0, "explanation": "Slide nêu tính chọn lọc đối với phản ứng và loại liên kết hoặc nhóm chức."}, {"id": "s01-q005", "page": 14, "prompt": "Cơ sở của tính đặc hiệu enzym là gì?", "options": ["Sự tương ứng cấu trúc không gian giữa trung tâm hoạt động và cơ chất", "Màu sắc của dung dịch", "Thể tích bình phản ứng", "Khối lượng dung môi"], "answer": 0, "explanation": "Slide gắn tính đặc hiệu với cấu trúc không gian của trung tâm hoạt động và cơ chất ở trạng thái chuyển tiếp."}, {"id": "s01-q006", "page": 15, "prompt": "Khoảng nhiệt độ tác dụng thường thích hợp được nêu ở slide này là bao nhiêu?", "options": ["30–50 °C", "0–5 °C", "100–120 °C", "150–200 °C"], "answer": 0, "explanation": "Đây là khoảng nhiệt độ trong mô tả chung của slide về điều kiện phản ứng êm dịu."}, {"id": "s01-q007", "page": 16, "prompt": "Kỹ thuật đột biến, xáo trộn DNA được nêu nhằm mục đích gì?", "options": ["Cải thiện độ bền và sự phù hợp của enzym với điều kiện sử dụng", "Loại bỏ hoàn toàn tính xúc tác", "Biến mọi enzym thành lipid", "Ngăn mọi sự tổng hợp enzym"], "answer": 0, "explanation": "Slide nêu hai mục tiêu: cải thiện độ bền enzym tự nhiên và thích ứng điều kiện sản xuất, sử dụng."}, {"id": "s01-q008", "page": 18, "prompt": "Vai trò nào của enzym trong kỹ thuật y sinh được nêu trong slide?", "options": ["Chỉ thị để chẩn đoán bệnh", "Thay thế hoàn toàn mọi phương pháp chẩn đoán", "Chỉ tạo cấu trúc xương", "Chỉ vận chuyển muối khoáng"], "answer": 0, "explanation": "Enzym được nêu là chỉ thị chẩn đoán, mục tiêu của thuốc và tác nhân điều trị."}, {"id": "s01-q009", "page": 19, "prompt": "Một IU tương ứng với lượng enzym chuyển hóa bao nhiêu cơ chất?", "options": ["1 micromol trong 1 phút", "1 mol trong 1 phút", "1 micromol trong 1 giờ", "1 mol trong 1 giờ"], "answer": 0, "explanation": "IU được xác định ở điều kiện tiêu chuẩn theo 1 micromol cơ chất mỗi phút."}, {"id": "s01-q010", "page": 19, "prompt": "Đơn vị katal tương ứng với tốc độ chuyển hóa nào?", "options": ["1 mol/giây", "1 micromol/phút", "1 miligam/giờ", "1 mol/ngày"], "answer": 0, "explanation": "Slide định nghĩa katal theo lượng 1 mol cơ chất được chuyển hóa trong 1 giây."}], "source": {"file": "1.1 Emzym 1.pdf", "url": "sources/s01.pdf", "pages": 19, "sha256": "5e3050c3507693bee77ffb60aa361e7f616df37059d9bcef421f28eeefe47480"}}, {"id": "s02", "title": "Enzym 1 · Phân loại và đo hoạt độ", "group": "Enzym học lâm sàng", "description": "Phân nhóm phản ứng, đơn vị đo và điều kiện xác định hoạt độ.", "sections": [{"title": "Vị trí và phân loại", "from": 4, "to": 7, "points": ["Enzym ngoại bào được tiết ra ngoài; enzym nội bào khu trú trong tế bào; slide còn giới thiệu enzym chu chất.", "Bộ slide trình bày 6 nhóm phản ứng: oxidoreductase, transferase, hydrolase, lyase, isomerase và ligase.", "Tên hệ thống của enzym kết hợp tên cơ chất với kiểu phản ứng."]}, {"title": "Đơn vị đo", "from": 10, "to": 12, "points": ["Hoạt độ phải gắn với lượng sản phẩm, thời gian và điều kiện phản ứng xác định.", "1 IU tương ứng 1 µmol/phút; 1 katal tương ứng 1 mol/giây; 1 µkatal/L = 60 U/L.", "Hoạt độ riêng là số đơn vị hoạt độ trên một đơn vị khối lượng protein của chế phẩm."]}, {"title": "Điều kiện phép đo", "from": 13, "to": 15, "points": ["Chọn giai đoạn có quan hệ tuyến tính giữa thời gian, lượng enzym và lượng sản phẩm.", "Giữ pH ổn định; đưa cơ chất, enzym và đệm về nhiệt độ phân tích trước phản ứng.", "Dùng cơ chất dư; bổ sung dư cofactor hoặc coenzym nếu enzym cần.", "Chọn cách dừng phản ứng thích hợp và có mẫu kiểm chứng; chuẩn bị, bảo quản dịch enzym và cơ chất tốt."]}], "questions": [{"id": "s02-q001", "page": 5, "prompt": "Enzym ngoại bào là enzym như thế nào?", "options": ["Được tiết ra bên ngoài tế bào", "Chỉ tồn tại trong nhân", "Luôn gắn với DNA", "Chỉ nằm trong ti thể"], "answer": 0, "explanation": "Slide phân biệt enzym ngoại bào với enzym khu trú bên trong tế bào."}, {"id": "s02-q002", "page": 6, "prompt": "Trong bảng phân loại của slide, hydrolase xúc tác kiểu phản ứng nào?", "options": ["Thủy phân", "Oxy hóa khử", "Sắp xếp nội phân tử", "Gắn hai phân tử bằng năng lượng XTP"], "answer": 0, "explanation": "Hydrolase là nhóm xúc tác phản ứng thủy phân."}, {"id": "s02-q003", "page": 6, "prompt": "Nhóm transferase có chức năng nào?", "options": ["Chuyển nhóm chức giữa các phân tử", "Chỉ thủy phân protein", "Chỉ tạo đồng phân cis–trans", "Chỉ gắn hai phân tử bằng ATP"], "answer": 0, "explanation": "Bảng phân loại mô tả transferase chuyển nhóm từ phân tử này sang phân tử khác."}, {"id": "s02-q004", "page": 6, "prompt": "Oxidoreductase xúc tác phản ứng nào?", "options": ["Oxy hóa khử", "Thủy phân", "Tạo đồng phân", "Gắn nhóm đường bằng thủy phân"], "answer": 0, "explanation": "Oxidoreductase được trình bày là nhóm enzym oxy hóa khử."}, {"id": "s02-q005", "page": 7, "prompt": "Isomerase xúc tác quá trình nào?", "options": ["Sắp xếp nội phân tử", "Thủy phân bắt buộc bằng nước", "Vận chuyển oxy trong máu", "Tạo liên kết bằng XTP trong mọi trường hợp"], "answer": 0, "explanation": "Slide mô tả isomerase gắn với sự sắp xếp trong một phân tử."}, {"id": "s02-q006", "page": 7, "prompt": "Nhóm enzym nào gắn hai phân tử với sự sử dụng liên kết giàu năng lượng của XTP?", "options": ["Ligase", "Hydrolase", "Isomerase", "Oxidoreductase"], "answer": 0, "explanation": "Ligase được minh họa bằng phản ứng nối hai phân tử có tiêu tốn năng lượng XTP."}, {"id": "s02-q007", "page": 7, "prompt": "Tên hệ thống của enzym được xây dựng từ những thành phần nào?", "options": ["Tên cơ chất và tên kiểu phản ứng", "Tên tác giả và năm phát hiện", "Tên mô và màu dung dịch", "Nhiệt độ và thể tích mẫu"], "answer": 0, "explanation": "Slide phân biệt tên thường gọi với tên hệ thống gồm cơ chất và kiểu phản ứng."}, {"id": "s02-q008", "page": 12, "prompt": "Hoạt độ riêng của một chế phẩm được biểu thị trên cơ sở nào?", "options": ["Đơn vị hoạt độ trên khối lượng protein", "Khối lượng protein trên thể tích nước", "Số tế bào trên khối lượng lipid", "Thể tích đệm trên số phân tử cơ chất"], "answer": 0, "explanation": "Hoạt độ riêng quy hoạt độ về một đơn vị khối lượng protein của chế phẩm."}, {"id": "s02-q009", "page": 12, "prompt": "Theo hệ số quy đổi của slide, 2 µkatal/L bằng bao nhiêu U/L?", "options": ["120 U/L", "30 U/L", "60 U/L", "2 U/L"], "answer": 0, "explanation": "Slide cho 1 µkatal/L = 60 U/L, nên 2 × 60 = 120 U/L."}, {"id": "s02-q010", "page": 13, "prompt": "Vì sao ưu tiên đo trong giai đoạn đầu của phản ứng enzym?", "options": ["Sự tạo sản phẩm còn tuyến tính theo thời gian", "Enzym chắc chắn đã biến tính hết", "Cơ chất đã cạn hoàn toàn", "Phản ứng nghịch luôn chiếm ưu thế"], "answer": 0, "explanation": "Phản ứng kéo dài có thể gây biến tính enzym, tiêu hao cơ chất và tăng ảnh hưởng phản ứng nghịch."}, {"id": "s02-q011", "page": 14, "prompt": "Khi xác định hoạt độ, vì sao cần dùng cơ chất dư?", "options": ["Để biến đổi lượng sản phẩm trong thời gian đo phụ thuộc vào lượng enzym", "Để lượng cơ chất trở thành yếu tố giới hạn chính", "Để loại bỏ mọi nhu cầu kiểm soát pH", "Để dừng ngay phản ứng"], "answer": 0, "explanation": "Slide yêu cầu cơ chất dư nhằm đo sự phụ thuộc của lượng sản phẩm vào nồng độ enzym."}, {"id": "s02-q012", "page": 14, "prompt": "Trước khi trộn bắt đầu phản ứng, các dung dịch cần được chuẩn bị thế nào?", "options": ["Đạt nhiệt độ phân tích", "Được đun sôi hết", "Được làm đông tất cả", "Có pH khác nhau tùy ý"], "answer": 0, "explanation": "Cơ chất, enzym và dung dịch đệm đều phải đạt nhiệt độ phân tích trước khi tiếp xúc."}, {"id": "s02-q013", "page": 14, "prompt": "Nếu enzym cần coenzym hoặc cofactor, slide yêu cầu điều gì khi đo?", "options": ["Dùng dư coenzym hoặc cofactor cần thiết", "Loại bỏ toàn bộ coenzym", "Chỉ bổ sung sau khi dừng phản ứng", "Thay bằng cùng thể tích nước"], "answer": 0, "explanation": "Điều kiện đo cần tránh việc thiếu thành phần hỗ trợ trở thành yếu tố giới hạn."}, {"id": "s02-q014", "page": 15, "prompt": "Mẫu kiểm chứng trong phép xác định hoạt độ có mục đích gì?", "options": ["Giúp tránh sai số do sản phẩm có sẵn hoặc ảnh hưởng ngoài phản ứng cần đo", "Thay thế việc đo mẫu thật", "Làm tăng lượng enzym trong mọi mẫu", "Bỏ qua bước dừng phản ứng"], "answer": 0, "explanation": "Slide yêu cầu luôn có mẫu kiểm chứng để kiểm soát các nguồn sai số."}], "source": {"file": "1.2 Enzym 1.pdf", "url": "sources/s02.pdf", "pages": 15, "sha256": "72bcc17f69260f18e31e046e24ce29e811283dfac6bac8ea9548ef07fc37d88f"}}, {"id": "s03", "title": "Enzym 2 · Chỉ thị và ứng dụng", "group": "Enzym học lâm sàng", "description": "Enzym huyết thanh, các chỉ thị thường gặp và ứng dụng điều trị.", "sections": [{"title": "Đọc kết quả enzym huyết thanh", "from": 6, "to": 11, "points": ["Phân biệt enzym huyết thanh có chức năng xúc tác trong máu và nhóm không thực hiện chức năng ở huyết thanh.", "Hoạt độ tăng có thể liên quan tổn thương mô, giảm thanh lọc, tăng số lượng hoặc hoạt tính tế bào, hay tăng sản sinh enzym.", "Cần xem mức hoạt độ, phối hợp các enzym, tỷ số, diễn biến theo thời gian và isozym."]}, {"title": "Các enzym tiêu biểu", "from": 12, "to": 23, "points": ["ACP được liên hệ với tuyến tiền liệt; ALT và AST tham gia chuyển nhóm amin.", "ALP có nhiều nguồn, đặc biệt tế bào đường mật và tạo cốt bào; xác định isozym giúp phân biệt nguồn.", "Amylase thủy phân liên kết α-1,4-glucosid; hai isozym chính là P từ tụy và S từ các nguồn như tuyến nước bọt.", "ACE chuyển angiotensin I thành angiotensin II; CK có các dạng MM, MB và BB."]}, {"title": "Các chỉ thị tiếp theo", "from": 25, "to": 35, "points": ["Elastase trong phân được dùng để đánh giá khả năng sản xuất enzym của tụy.", "G6PD liên quan chuyển hóa glucose và bảo vệ tế bào trước stress oxy hóa.", "GLDH, GGT, glycogen phosphorylase và LDH có các vai trò chuyển hóa khác nhau; LDH chuyển đổi lactate và pyruvate.", "Lipase phân giải lipid; trypsin tiêu hóa protein; cả hai được trình bày gắn với tuyến tụy."]}, {"title": "Enzym và điều trị", "from": 36, "to": 39, "points": ["Slide nêu các ứng dụng như làm tan huyết khối và liệu pháp thay thế khi thiếu hụt enzym.", "Một số thuốc tác động bằng ức chế enzym: cạnh tranh tại trung tâm hoạt động hoặc tác động ở vị trí khác."]}], "questions": [{"id": "s03-q001", "page": 6, "prompt": "Enzym huyết thanh có chức năng được mô tả như thế nào?", "options": ["Được bài tiết vào máu và thực hiện xúc tác trong máu", "Luôn không có cơ chất trong huyết thanh", "Chỉ có trong nước tiểu", "Chỉ giải phóng khi tế bào đã chết"], "answer": 0, "explanation": "Slide phân nhóm dựa trên việc enzym có thực hiện chức năng xúc tác trong máu hay không."}, {"id": "s03-q002", "page": 7, "prompt": "Ở trạng thái ổn định, tốc độ giải phóng enzym vào huyết thanh cân bằng với yếu tố nào?", "options": ["Tốc độ thanh lọc protein enzym khỏi huyết thanh", "Tốc độ tạo hồng cầu duy nhất", "Tốc độ đông máu duy nhất", "Tốc độ uống nước"], "answer": 0, "explanation": "Sơ đồ cân bằng đặt tốc độ giải phóng đối diện tốc độ thanh lọc enzym."}, {"id": "s03-q003", "page": 8, "prompt": "Ngoài tổn thương tế bào, cơ chế nào có thể làm tăng hoạt độ enzym trong huyết thanh?", "options": ["Giảm thanh lọc enzym", "Tăng thanh lọc mà không đổi giải phóng", "Loại hết cơ chất trước lấy mẫu", "Không còn enzym trong mô"], "answer": 0, "explanation": "Slide nêu giảm độ thanh lọc là một nguyên nhân gây tăng hoạt độ."}, {"id": "s03-q004", "page": 11, "prompt": "Thông tin nào giúp diễn giải hoạt độ enzym tốt hơn?", "options": ["Phối hợp các enzym, tỷ số và diễn biến theo thời gian", "Chỉ màu của ống nghiệm", "Chỉ một giá trị tách khỏi bối cảnh", "Chỉ thể tích dung dịch đệm"], "answer": 0, "explanation": "Slide yêu cầu xem mức hoạt độ, loại hình enzym, tỷ số, diễn biến và isozym."}, {"id": "s03-q005", "page": 12, "prompt": "ACP xúc tác kiểu phản ứng nào được nêu trong slide?", "options": ["Thủy phân monoeste phosphate", "Tạo glycogen từ glucose", "Chuyển lactate thành pyruvate", "Gắn oxy vào hemoglobin"], "answer": 0, "explanation": "ACP giải phóng nhóm phosphate; phản ứng tạo rượu và phosphate."}, {"id": "s03-q006", "page": 14, "prompt": "ALT chuyển nhóm amin từ L-alanine cho chất nào?", "options": ["α-Ketoglutarate", "Cholesterol", "Lactose", "Glycerol"], "answer": 0, "explanation": "Phản ứng ALT trong slide tạo pyruvate và L-glutamate."}, {"id": "s03-q007", "page": 16, "prompt": "Hai nguồn nổi bật của ALP được nêu là gì?", "options": ["Tế bào đường mật và tạo cốt bào", "Chỉ hồng cầu và tiểu cầu", "Chỉ tế bào võng mạc", "Chỉ tuyến nước bọt"], "answer": 0, "explanation": "Slide mô tả ALP chủ yếu ở tế bào phủ đường mật và tế bào tạo xương."}, {"id": "s03-q008", "page": 18, "prompt": "Khi ALP tăng, xác định các isoenzym giúp làm gì?", "options": ["Phân biệt nguồn gốc enzym", "Xác định trực tiếp nhóm máu ABO", "Đo nồng độ glucose thay cho mọi xét nghiệm", "Loại bỏ nhu cầu xem bối cảnh"], "answer": 0, "explanation": "Nguồn ALP khác nhau có thể được phân biệt qua các isoenzym."}, {"id": "s03-q009", "page": 19, "prompt": "Amylase thủy phân loại liên kết nào trong tinh bột và glycogen?", "options": ["α-1,4-glucosid", "β-1,4-glucosid của cellulose", "Liên kết peptide", "Cầu disulfide"], "answer": 0, "explanation": "Slide nêu tác dụng thủy phân liên kết α-1,4-glucosid."}, {"id": "s03-q010", "page": 20, "prompt": "Isoenzym P của amylase có nguồn gốc chính từ đâu?", "options": ["Tụy", "Xương", "Não", "Tuyến giáp"], "answer": 0, "explanation": "Slide phân biệt P từ tụy với S từ tuyến nước bọt và một số nguồn khác."}, {"id": "s03-q011", "page": 21, "prompt": "ACE chuyển hóa angiotensin I thành chất nào?", "options": ["Angiotensin II", "Albumin", "Insulin", "Glucagon"], "answer": 0, "explanation": "Slide nêu angiotensin II là chất co mạch tạo ra nhờ ACE."}, {"id": "s03-q012", "page": 22, "prompt": "Tên khác của AST là gì?", "options": ["SGOT", "SGPT", "LPL", "LCAT"], "answer": 0, "explanation": "AST được ghi là serum glutamic-oxaloacetic transaminase, viết tắt SGOT."}, {"id": "s03-q013", "page": 23, "prompt": "Isoenzym CK nào được nêu chủ yếu có trong tim?", "options": ["CK-MB", "CK-MM", "CK-BB", "ALP"], "answer": 0, "explanation": "Slide phân biệt CK-MB ở tim, CK-MM ở cơ và CK-BB ở não."}, {"id": "s03-q014", "page": 25, "prompt": "Mẫu nào thường được dùng để xét nghiệm elastase đánh giá tụy theo slide?", "options": ["Phân", "Tóc", "Móng", "Dịch khớp"], "answer": 0, "explanation": "Slide cho biết xét nghiệm elastase trong phân phổ biến hơn xét nghiệm trong máu."}, {"id": "s03-q015", "page": 26, "prompt": "G6PD có vai trò nổi bật nào?", "options": ["Bảo vệ tế bào khỏi stress oxy hóa", "Trực tiếp vận chuyển oxy như hemoglobin", "Thủy phân mọi liên kết peptide", "Là kháng thể IgG"], "answer": 0, "explanation": "Slide liên hệ G6PD với chuyển hóa glucose và bảo vệ trước tác nhân oxy hóa."}, {"id": "s03-q016", "page": 29, "prompt": "Glycogen phosphorylase liên quan chủ yếu đến chuyển hóa chất nào?", "options": ["Glycogen", "Cholesterol", "Albumin", "Bilirubin"], "answer": 0, "explanation": "Slide nêu vai trò trong chuyển hóa glycogen và liên hệ thiếu enzym ở cơ với bệnh McArdle."}, {"id": "s03-q017", "page": 30, "prompt": "LDH xúc tác sự chuyển đổi giữa cặp chất nào?", "options": ["Lactate và pyruvate", "Glucose và cholesterol", "Ure và albumin", "Glycerol và hemoglobin"], "answer": 0, "explanation": "LDH chuyển lactate thành pyruvate và ngược lại."}, {"id": "s03-q018", "page": 32, "prompt": "Cơ chất thuộc nhóm nào được lipase phân giải?", "options": ["Lipid", "Axit nucleic", "Muối khoáng", "Protein cấu trúc"], "answer": 0, "explanation": "Slide minh họa sự thủy phân triacylglycerol bởi lipase."}, {"id": "s03-q019", "page": 34, "prompt": "Trypsin tham gia chủ yếu vào quá trình nào?", "options": ["Tiêu hóa protein", "Vận chuyển đồng", "Tạo áp suất keo huyết tương", "Tổng hợp kháng thể"], "answer": 0, "explanation": "Trypsin là enzym tiêu hóa do tụy sản xuất, có vai trò tiêu hóa protein."}, {"id": "s03-q020", "page": 36, "prompt": "Liệu pháp thay thế enzym được trình bày cho trường hợp nào?", "options": ["Bệnh do thiếu hụt một enzym hoặc hệ enzym", "Mọi thay đổi màu da", "Mọi trường hợp chỉ thiếu nước", "Mọi trường hợp tăng chiều cao"], "answer": 0, "explanation": "Slide nêu liệu pháp thay thế cho bệnh di truyền thiếu hụt enzym hoặc hệ enzym."}, {"id": "s03-q021", "page": 37, "prompt": "Công nghệ DNA giúp ích gì cho việc chuẩn bị enzym dùng cho người?", "options": ["Tạo enzym có nguồn gốc người để giảm vấn đề miễn dịch và độc tính từ nguồn vi khuẩn", "Làm mọi protein hoàn toàn không thể bị phân hủy", "Biến enzym thành phân tử không cần cơ chất", "Loại bỏ hoàn toàn nhu cầu sản xuất"], "answer": 0, "explanation": "Slide nhấn mạnh lợi ích của enzym nguồn gốc người trong sử dụng điều trị."}, {"id": "s03-q022", "page": 39, "prompt": "Chất kìm hãm cạnh tranh thường gắn vào đâu?", "options": ["Trung tâm hoạt động của enzym", "Nhân của mọi tế bào", "Chỉ màng hồng cầu", "Chỉ vùng lipid của huyết tương"], "answer": 0, "explanation": "Slide mô tả chất cạnh tranh có cấu tạo tương tự cơ chất và gắn vào trung tâm hoạt động."}], "source": {"file": "2.1 Enzym 2.pdf", "url": "sources/s03.pdf", "pages": 39, "sha256": "599c1f7745184e804c9ed7b4e02317ec7f74316053f65348008851598cb3d466"}}, {"id": "s04", "title": "Enzym 2 · Cấu tạo và điều hòa", "group": "Enzym học lâm sàng", "description": "Apoenzym, trung tâm hoạt động, chất ức chế, nhiệt độ và pH.", "sections": [{"title": "Cấu tạo và trung tâm hoạt động", "from": 1, "to": 5, "points": ["Enzym một thành phần chỉ có protein; enzym hai thành phần gồm protein và phần phi protein.", "Apoenzym là phần protein; phần phi protein có thể là ion kim loại hoặc coenzym.", "Trung tâm hoạt động trực tiếp gắn cơ chất, tạo hoặc cắt liên kết; các nhóm chức có thể xa nhau trong trình tự nhưng gần nhau trong không gian.", "Các ví dụ gồm carboxypeptidase A có Zn²⁺ và lactate dehydrogenase dùng NAD⁺."]}, {"title": "Đặc hiệu và ảnh hưởng của nồng độ", "from": 6, "to": 11, "points": ["Chất gắn vào trung tâm dị lập thể có thể đổi cấu hình và hoạt tính enzym.", "Phân biệt đặc hiệu kiểu phản ứng, đặc hiệu tuyệt đối, nhóm, liên kết và lập thể.", "Slide minh họa tốc độ phản ứng tiến tới mức bão hòa khi tăng cơ chất trong điều kiện lượng enzym cố định."]}, {"title": "Kìm hãm và hoạt hóa", "from": 12, "to": 15, "points": ["Chất kìm hãm cạnh tranh cùng tác động vào trung tâm hoạt động với cơ chất; tăng cơ chất có thể giải tỏa ức chế.", "Kìm hãm không cạnh tranh tác động ở vị trí khác; kìm hãm bất thuận nghịch còn tồn tại sau thẩm tích loại chất kìm hãm.", "Chất hoạt hóa chuyển enzym từ không hoạt động hoặc hoạt động yếu sang hoạt động mạnh hơn.", "Hoạt hóa gián tiếp loại tác nhân kìm hãm; hoạt hóa trực tiếp có thể liên quan coenzym, cofactor hoặc phục hồi nhóm chức."]}, {"title": "Nhiệt độ, pH và tinh chế", "from": 15, "to": 18, "points": ["Nhiệt độ tối ưu tùy enzym và nguồn chế phẩm; slide có các ví dụ enzym chịu nhiệt.", "pH ảnh hưởng trạng thái ion hóa trung tâm hoạt động và độ bền của enzym.", "Pepsin và trypsin được minh họa có vùng pH hoạt động khác nhau.", "Cuối file giới thiệu quy trình thu nhận và ví dụ tinh chế bằng sắc ký trao đổi anion trên hệ FPLC."]}], "questions": [{"id": "s04-q001", "page": 1, "prompt": "Enzym một thành phần có cấu tạo nào?", "options": ["Chỉ có protein", "Chỉ có lipid", "Protein và một phần phi protein bắt buộc", "Chỉ có ion kim loại"], "answer": 0, "explanation": "Sơ đồ phân biệt enzym một thành phần với enzym hai thành phần."}, {"id": "s04-q002", "page": 2, "prompt": "Apoenzym là phần nào của enzym hai thành phần?", "options": ["Phần protein", "Phần nước", "Toàn bộ cơ chất", "Chỉ ion kim loại"], "answer": 0, "explanation": "Slide gọi phần protein là apoenzym."}, {"id": "s04-q003", "page": 2, "prompt": "Theo slide, phần protein chủ yếu quyết định tính đặc hiệu nào?", "options": ["Đặc hiệu cơ chất", "Màu của sản phẩm", "Nhiệt độ môi trường", "Thể tích mẫu"], "answer": 0, "explanation": "Sơ đồ gắn vai trò quyết định tính đặc hiệu cơ chất với apoenzym."}, {"id": "s04-q004", "page": 3, "prompt": "Trung tâm hoạt động có chức năng nào?", "options": ["Gắn cơ chất và trực tiếp tham gia biến đổi liên kết", "Chỉ tích trữ nước", "Chỉ nối enzym với màng nhân", "Luôn nằm ngoài phân tử enzym"], "answer": 0, "explanation": "Trung tâm hoạt động là phần nhỏ của enzym trực tiếp tham gia quá trình xúc tác."}, {"id": "s04-q005", "page": 3, "prompt": "Các nhóm chức tạo trung tâm hoạt động được sắp xếp như thế nào?", "options": ["Có thể xa nhau ở cấu trúc bậc 1 nhưng gần nhau trong không gian", "Luôn liền nhau trong trình tự axit amin", "Luôn thuộc các tế bào khác nhau", "Luôn cách nhau vô hạn"], "answer": 0, "explanation": "Sự gấp cuộn đưa các nhóm chức thích hợp đến gần nhau."}, {"id": "s04-q006", "page": 4, "prompt": "Ion kim loại nào được nêu ở trung tâm hoạt động của carboxypeptidase A?", "options": ["Zn²⁺", "Na⁺", "K⁺", "Cl⁻"], "answer": 0, "explanation": "Ví dụ enzym hai cấu tử trong slide có chứa ion Zn²⁺."}, {"id": "s04-q007", "page": 5, "prompt": "Coenzym nào được nêu cho lactate dehydrogenase?", "options": ["NAD⁺", "ATP", "Biotin", "Heme"], "answer": 0, "explanation": "Slide minh họa lactate dehydrogenase với coenzym NAD⁺."}, {"id": "s04-q008", "page": 6, "prompt": "Khi chất có khối lượng phân tử nhỏ gắn vào trung tâm dị lập thể, điều gì có thể xảy ra?", "options": ["Thay đổi cấu hình không gian và hoạt tính enzym", "Luôn cắt hết liên kết peptide", "Luôn tạo thành axit nucleic", "Không thể có thay đổi nào"], "answer": 0, "explanation": "Trung tâm dị lập thể liên hệ sự gắn chất điều hòa với biến đổi cấu hình và hoạt tính."}, {"id": "s04-q009", "page": 9, "prompt": "Nhóm nào xúc tác phản ứng chuyển nhóm chức?", "options": ["Transferase", "Hydrolase", "Isomerase", "Ligase"], "answer": 0, "explanation": "Bảng phân loại trong slide mô tả transferase chuyển nhóm giữa các phân tử."}, {"id": "s04-q010", "page": 10, "prompt": "Đặc hiệu tuyệt đối của enzym nghĩa là gì?", "options": ["Chỉ chuyển hóa một cơ chất xác định hoặc cặp cơ chất xác định", "Tác động lên mọi cơ chất với tốc độ bằng nhau", "Không cần cơ chất", "Chỉ phụ thuộc màu sắc dung dịch"], "answer": 0, "explanation": "Slide định nghĩa đặc hiệu tuyệt đối theo cơ chất và phản ứng xác định."}, {"id": "s04-q011", "page": 10, "prompt": "Đặc hiệu lập thể nghĩa là enzym tác động thế nào?", "options": ["Chọn một trong các đồng phân không gian của chất", "Tác động như nhau lên mọi đồng phân", "Chỉ chọn theo thể tích dung dịch", "Không có sự chọn lọc cơ chất"], "answer": 0, "explanation": "Tính đặc hiệu lập thể gắn với cấu trúc không gian của cơ chất."}, {"id": "s04-q012", "page": 11, "prompt": "Đồ thị tốc độ theo nồng độ cơ chất trong slide thể hiện điều gì khi cơ chất tăng cao?", "options": ["Tốc độ tiến tới mức bão hòa", "Tốc độ tăng tuyến tính vô hạn", "Tốc độ luôn bằng không", "Enzym chắc chắn biến thành cơ chất"], "answer": 0, "explanation": "Đồ thị minh họa giới hạn tốc độ khi các trung tâm enzym được cơ chất chiếm."}, {"id": "s04-q013", "page": 12, "prompt": "Cách nào có thể giải tỏa kìm hãm cạnh tranh theo slide?", "options": ["Tăng nồng độ cơ chất", "Loại hết cơ chất", "Giảm lượng cơ chất về không", "Chỉ tăng thể tích ống nghiệm"], "answer": 0, "explanation": "Cơ chất và chất kìm hãm cạnh tranh cùng vị trí nên tăng cơ chất có thể giảm tác dụng kìm hãm."}, {"id": "s04-q014", "page": 12, "prompt": "Chất kìm hãm không cạnh tranh tác động thế nào so với cơ chất?", "options": ["Ở vị trí khác trên enzym", "Luôn cùng vị trí tại trung tâm hoạt động", "Chỉ gắn vào sản phẩm sau phản ứng", "Chỉ làm đổi màu đệm"], "answer": 0, "explanation": "Slide phân biệt sự tác động lên các vị trí khác nhau trên enzym."}, {"id": "s04-q015", "page": 13, "prompt": "Đặc điểm nào cho thấy kìm hãm bất thuận nghịch?", "options": ["Tác dụng vẫn còn sau thẩm tích loại chất kìm hãm", "Tác dụng mất ngay khi tăng một ít cơ chất", "Không tạo tương tác với enzym", "Chỉ xuất hiện khi không có enzym"], "answer": 0, "explanation": "Slide nêu tiêu chí tác dụng không bị loại bỏ khi đã thẩm tích chất kìm hãm."}, {"id": "s04-q016", "page": 14, "prompt": "Chất hoạt hóa enzym có thể tạo ra thay đổi nào?", "options": ["Chuyển enzym hoạt động yếu sang hoạt động mạnh hơn", "Luôn phá hủy hoàn toàn enzym", "Luôn làm mất mọi cơ chất", "Biến sản phẩm thành muối vô cơ"], "answer": 0, "explanation": "Chất hoạt hóa làm tăng trạng thái hoạt động của enzym."}, {"id": "s04-q017", "page": 14, "prompt": "Hoạt hóa gián tiếp được mô tả bằng cơ chế nào?", "options": ["Loại chất kìm hãm khỏi hỗn hợp phản ứng", "Luôn gắn vào trung tâm hoạt động", "Luôn cắt mọi liên kết peptide", "Luôn tăng lượng cơ chất thành vô hạn"], "answer": 0, "explanation": "Slide phân biệt tác động gián tiếp với tác động trực tiếp lên phân tử enzym."}, {"id": "s04-q018", "page": 15, "prompt": "Nhiệt độ tối ưu của enzym được mô tả như thế nào?", "options": ["Khác nhau tùy enzym và nguồn chế phẩm", "Luôn đúng 37 °C với mọi enzym", "Luôn đúng 100 °C", "Không liên quan nguồn enzym"], "answer": 0, "explanation": "Slide nhấn mạnh sự khác nhau của nhiệt độ tối ưu và đưa ví dụ enzym chịu nhiệt."}, {"id": "s04-q019", "page": 16, "prompt": "pH thay đổi có thể ảnh hưởng trung tâm hoạt động qua cơ chế nào?", "options": ["Thay đổi trạng thái ion hóa các nhóm chức", "Chỉ thay đổi màu sắc cơ chất", "Luôn làm tăng số phân tử enzym", "Chỉ làm đổi thể tích dung dịch"], "answer": 0, "explanation": "Sự ion hóa nhóm chức tại trung tâm hoạt động ảnh hưởng tốc độ phản ứng."}, {"id": "s04-q020", "page": 16, "prompt": "pH quá axit hoặc quá kiềm có thể làm gì với enzym?", "options": ["Gây biến tính và giảm vận tốc phản ứng", "Luôn làm enzym bền hơn", "Không bao giờ ảnh hưởng enzym", "Chỉ làm tăng lượng sản phẩm sẵn có"], "answer": 0, "explanation": "Ngoài ion hóa, pH còn tác động đến độ bền cấu trúc enzym."}, {"id": "s04-q021", "page": 17, "prompt": "Enzym nào được minh họa hoạt động ở vùng pH axit mạnh?", "options": ["Pepsin", "Trypsin", "Arginase", "Subtilisin"], "answer": 0, "explanation": "Đồ thị đặt pepsin ở vùng pH thấp, khác với trypsin ở vùng kiềm."}, {"id": "s04-q022", "page": 18, "prompt": "Ví dụ tinh chế enzym cuối file sử dụng phương pháp nào?", "options": ["Sắc ký trao đổi anion trên FPLC", "Chỉ ly tâm máu", "Chỉ thử Benedict", "Chỉ chuẩn độ axit béo"], "answer": 0, "explanation": "Slide cuối minh họa cột Mono Q trong hệ FPLC dùng trao đổi anion."}], "source": {"file": "2.2 Enzym 2.pdf", "url": "sources/s04.pdf", "pages": 18, "sha256": "b2662a4d4b11cd3bd647aa89c438bee5a53070763c7d9673240dac4d496b65c8"}}, {"id": "s05", "title": "Gluxit · Cấu tạo và tính chất", "group": "Gluxit", "description": "Đường đơn, đồng phân, phản ứng nhận biết và oligosaccharide.", "sections": [{"title": "Khái niệm và phân loại", "from": 1, "to": 13, "points": ["Gluxit gồm các dẫn xuất aldehyde hoặc ketone của rượu đa chức và các chất khi thủy phân tạo những dẫn xuất đó.", "Vai trò: cung cấp, dự trữ năng lượng; tạo cấu trúc; bảo vệ và tham gia tương tác tế bào.", "Theo bảng phân loại trang 10: monosaccharide có 1 đơn vị đường; oligosaccharide có 2–10; polysaccharide có trên 10.", "Aldose có nhóm aldehyde; ketose có nhóm ketone. Glyceraldehyde là aldotriose, fructose là ketohexose."]}, {"title": "Cấu trúc và tạo vòng", "from": 14, "to": 34, "points": ["Slide trình bày các cấu trúc mạch thẳng và dạng vòng của monosaccharide.", "Phản ứng giữa aldehyde và alcohol tạo hemiacetal; giữa ketone và alcohol tạo hemiketal.", "Furanose có vòng 5 cạnh; pyranose có vòng 6 cạnh.", "Hai dạng α và β của glucopyranose khác nhau tại C1; hình fructofuranose minh họa sự khác nhau tại C2."]}, {"title": "Tính chất và nhận biết", "from": 35, "to": 49, "points": ["Đường đơn tan trong nước; độ hòa tan phụ thuộc loại đường và nhiệt độ.", "Sucrose được chọn làm chuẩn so sánh độ ngọt trong bảng của slide.", "Fehling, Benedict và DNS được giới thiệu dựa trên tính khử; phép glucose oxidase–peroxidase dùng định lượng glucose.", "Khử nhóm carbonyl của glucose tạo sorbitol; nhóm OH có thể tạo liên kết glycosid hoặc este phosphate."]}, {"title": "Biến đổi khi gia nhiệt", "from": 50, "to": 57, "points": ["Trong môi trường axit mạnh, phản ứng loại nước có thể tạo hợp chất furan như HMF.", "Caramel hóa gồm loại nước và các phản ứng tiếp theo tạo màu, mùi.", "Maillard là phản ứng tạo màu phi enzym giữa nhóm amin và hợp chất carbonyl; các sản phẩm trung gian có thể tạo melanoidin màu nâu."]}, {"title": "Oligosaccharide", "from": 58, "to": 65, "points": ["Disaccharide còn nhóm lactol tự do có tính khử; nếu hai nhóm lactol cùng tham gia liên kết thì không có tính khử.", "Maltose và cellobiose đều cấu tạo từ hai gốc glucose nhưng khác liên kết α-1,4 và β-1,4.", "Saccharose gồm glucose và fructose; slide trình bày sự thủy phân và các enzym tương ứng.", "File hiện kết thúc ở raffinose; phần ghi nhớ và quiz giới hạn ở nội dung đã có trong PDF."]}], "questions": [{"id": "s05-q001", "page": 1, "prompt": "Theo slide, gluxit là dẫn xuất của nhóm hợp chất nào?", "options": ["Rượu đa chức", "Chỉ axit béo no", "Chỉ protein hình sợi", "Chỉ muối vô cơ"], "answer": 0, "explanation": "Định nghĩa liên hệ gluxit với dẫn xuất aldehyde hoặc ketone của rượu đa chức."}, {"id": "s05-q002", "page": 2, "prompt": "Vai trò sinh học nào của gluxit được nêu trong slide?", "options": ["Dự trữ, cung cấp năng lượng và chất trao đổi trung gian", "Chỉ xúc tác phân giải protein", "Chỉ vận chuyển đồng trong máu", "Chỉ tổng hợp muối khoáng"], "answer": 0, "explanation": "Slide liệt kê vai trò năng lượng bên cạnh vai trò cấu trúc, bảo vệ và tương tác tế bào."}, {"id": "s05-q003", "page": 10, "prompt": "Theo bảng phân loại ở trang 10, oligosaccharide có bao nhiêu gốc đường đơn?", "options": ["2–10", "Chỉ 1", "Luôn trên 100", "Luôn bằng 20"], "answer": 0, "explanation": "Bảng phân loại quy oligosaccharide vào nhóm 2–10 gốc đường đơn."}, {"id": "s05-q004", "page": 10, "prompt": "Các gốc đường nối với nhau bằng liên kết gì?", "options": ["Glycosid", "Peptide", "Disulfide", "Phosphodiester trong mọi trường hợp"], "answer": 0, "explanation": "Slide mô tả cầu oxy nối các gốc đường thành liên kết glycosid."}, {"id": "s05-q005", "page": 11, "prompt": "Aldose chứa nhóm chức đặc trưng nào?", "options": ["Aldehyde", "Amide", "Thiol", "Phosphate"], "answer": 0, "explanation": "Sơ đồ phân biệt nhóm aldehyde của aldose với nhóm ketone của ketose."}, {"id": "s05-q006", "page": 13, "prompt": "D-Fructose được phân loại như thế nào trong ví dụ?", "options": ["Ketohexose", "Aldotriose", "Aldopentose", "Ketotetrose"], "answer": 0, "explanation": "Fructose có sáu carbon và nhóm ketone trong hình mạch thẳng."}, {"id": "s05-q007", "page": 13, "prompt": "D-Glyceraldehyde thuộc nhóm nào?", "options": ["Aldotriose", "Ketohexose", "Aldohexose", "Ketopentose"], "answer": 0, "explanation": "Ví dụ xác định glyceraldehyde có ba carbon và nhóm aldehyde."}, {"id": "s05-q008", "page": 27, "prompt": "Phản ứng giữa alcohol và aldehyde tạo sản phẩm gì?", "options": ["Hemiacetal", "Hemiketal", "Liên kết peptide", "Triacylglycerol"], "answer": 0, "explanation": "Slide dùng tên hemiacetal cho sản phẩm giữa alcohol và aldehyde."}, {"id": "s05-q009", "page": 29, "prompt": "Phản ứng giữa alcohol và ketone tạo sản phẩm gì?", "options": ["Hemiketal", "Hemiacetal", "Protein", "Muối mật"], "answer": 0, "explanation": "Slide mô tả sản phẩm cộng alcohol vào ketone là hemiketal."}, {"id": "s05-q010", "page": 31, "prompt": "Vòng furanose có bao nhiêu cạnh?", "options": ["5", "3", "4", "6"], "answer": 0, "explanation": "Hình so sánh furanose năm cạnh với pyranose sáu cạnh."}, {"id": "s05-q011", "page": 33, "prompt": "Hai dạng α và β của glucopyranose khác nhau tại carbon nào?", "options": ["C1", "C3", "C5", "C6"], "answer": 0, "explanation": "Slide ghi rõ hai đồng phân α và β của hemiacetal glucose tại C1."}, {"id": "s05-q012", "page": 34, "prompt": "Trong hình fructofuranose, hai dạng α và β khác nhau tại carbon nào?", "options": ["C2", "C1", "C4", "C6"], "answer": 0, "explanation": "Hình tạo hemiketal nội phân tử của fructose ghi vị trí α và β ở C2."}, {"id": "s05-q013", "page": 35, "prompt": "Đường nào được slide nêu có khả năng hút ẩm mạnh nhất trong phần này?", "options": ["Fructose", "Glucose", "Lactose", "Maltose"], "answer": 0, "explanation": "Trang tính chất hút ẩm nhấn mạnh fructose hút ẩm mạnh nhất."}, {"id": "s05-q014", "page": 37, "prompt": "Chất nào được chọn làm chuẩn so sánh độ ngọt trong bảng?", "options": ["Sucrose", "Glycerol", "Albumin", "NaCl"], "answer": 0, "explanation": "Slide chọn sucrose, còn gọi saccharose, làm chất chuẩn độ ngọt."}, {"id": "s05-q015", "page": 39, "prompt": "Phản ứng Fehling khai thác tính chất nào của monosaccharide?", "options": ["Tính khử", "Khả năng tạo liên kết peptide", "Tính chống đông", "Khả năng tạo micelle"], "answer": 0, "explanation": "Monosaccharide khử ion đồng trong phản ứng, tạo Cu₂O theo sơ đồ."}, {"id": "s05-q016", "page": 43, "prompt": "Theo bảng Benedict, dung dịch vẫn màu xanh lam thể hiện điều gì?", "options": ["Không phát hiện đường khử", "Hàm lượng đường khử cao nhất", "Có kết tủa đỏ gạch", "Có lượng protein cao nhất"], "answer": 0, "explanation": "Bảng quan sát ghi xanh lam là không có đường khử trong phép thử."}, {"id": "s05-q017", "page": 44, "prompt": "Thuốc thử DNS trong phần này dùng để làm gì?", "options": ["Định lượng monosaccharide dựa trên tính khử", "Đo albumin bằng điện di", "Định lượng natri", "Tạo lipoprotein"], "answer": 0, "explanation": "Slide giới thiệu axit 3,5-dinitrosalicylic cho định lượng monosaccharide."}, {"id": "s05-q018", "page": 45, "prompt": "Phản ứng glucose oxidase trong slide tạo chất nào để tiếp tục phản ứng hiện màu?", "options": ["H₂O₂", "Ure", "Ammonium sulfate", "Acetyl-CoA"], "answer": 0, "explanation": "Glucose oxidase tạo gluconic acid và H₂O₂; H₂O₂ tham gia phản ứng với peroxidase."}, {"id": "s05-q019", "page": 47, "prompt": "Sản phẩm polyalcohol tạo từ sự khử glucose trong sơ đồ là gì?", "options": ["Sorbitol", "Cholesterol", "Glycine", "Lactate"], "answer": 0, "explanation": "Sơ đồ chuyển glucose thành D-glucitol, còn gọi sorbitol."}, {"id": "s05-q020", "page": 49, "prompt": "Nhóm chức nào của đường đơn có thể tạo este với axit?", "options": ["Nhóm OH alcohol", "Chỉ nguyên tử carbon không có nhóm chức", "Nhóm peptide", "Cầu disulfide"], "answer": 0, "explanation": "Slide trình bày sự tạo este từ các nhóm OH, gồm các este phosphate."}, {"id": "s05-q021", "page": 54, "prompt": "Phản ứng Maillard được xếp vào loại nào?", "options": ["Tạo màu phi enzym", "Xúc tác enzym bắt buộc", "Điện di protein", "Trao đổi ion qua màng"], "answer": 0, "explanation": "Slide định nghĩa Maillard là phản ứng tạo màu phi enzym."}, {"id": "s05-q022", "page": 54, "prompt": "Hai nhóm thành phần tham gia Maillard là gì?", "options": ["Amin và hợp chất carbonyl", "Chỉ nước và oxy", "Chỉ muối NaCl và KCl", "Chỉ cholesterol và phospholipid"], "answer": 0, "explanation": "Nhóm amin từ axit amin hoặc protein phản ứng với nhóm carbonyl của đường."}, {"id": "s05-q023", "page": 57, "prompt": "Sản phẩm màu nâu cuối quá trình Maillard được gọi là gì?", "options": ["Melanoidin", "Hemoglobin", "Bilirubin", "Ceruloplasmin"], "answer": 0, "explanation": "Slide mô tả ngưng tụ, trùng hợp sản phẩm trung gian tạo melanoidin."}, {"id": "s05-q024", "page": 58, "prompt": "Disaccharide không khử hình thành khi nào theo sơ đồ?", "options": ["Hai nhóm lactol cùng tham gia liên kết", "Luôn còn một nhóm lactol tự do", "Chỉ có một gốc đường đơn", "Không có liên kết glycosid"], "answer": 0, "explanation": "Slide phân biệt lactol–lactol tạo disaccharide không khử với lactol–OH alcohol tạo loại khử."}, {"id": "s05-q025", "page": 61, "prompt": "Liên kết giữa hai gốc glucose trong maltose là gì?", "options": ["α-1,4-glucosid", "β-1,4-glucosid", "α-1,6 trong mọi phân tử", "Liên kết peptide"], "answer": 0, "explanation": "Trang maltose ghi liên kết α-1,4-glucosid."}, {"id": "s05-q026", "page": 62, "prompt": "Cellobiose khác maltose ở liên kết nào?", "options": ["Có liên kết β-1,4-glucosid", "Có liên kết peptide", "Không có glucose", "Chỉ có một carbon"], "answer": 0, "explanation": "Cả hai gồm hai gốc D-glucose, nhưng cellobiose có liên kết β-1,4."}, {"id": "s05-q027", "page": 64, "prompt": "Saccharose thủy phân tạo cặp đường nào?", "options": ["Glucose và fructose", "Glucose và galactose", "Hai fructose", "Hai galactose"], "answer": 0, "explanation": "Sơ đồ thủy phân saccharose tạo D-glucose và D-fructose."}, {"id": "s05-q028", "page": 64, "prompt": "Enzym nào được ghi với tên beta-fructofuranosidase?", "options": ["Invertase", "Trypsin", "Lipase", "Catalase"], "answer": 0, "explanation": "Slide gọi invertase là beta-fructofuranosidase, tác động ở phía fructose của liên kết."}], "source": {"file": "3. Gluxit 1.pdf", "url": "sources/s05.pdf", "pages": 65, "sha256": "a46472e9b7a989f0fd8e1305aceaec82fe51fefe5d33294e8858816dcc99ddfd"}}, {"id": "s06", "title": "Axit amin, peptide và protein huyết thanh", "group": "Protein", "description": "Cấu trúc, chuyển hóa, protein máu và phương pháp phân tích.", "sections": [{"title": "Axit amin và peptide", "from": 4, "to": 34, "points": ["Đặc tính axit amin phụ thuộc mạch bên R; ở điều kiện sinh lý thường tồn tại dạng lưỡng cực.", "Axit amin ở tế bào động vật có vú chủ yếu là dạng L; axit amin thiết yếu là loại cơ thể không tổng hợp được.", "Liên kết peptide là liên kết CO–NH giữa các axit amin.", "Ninhydrin dùng nhận biết axit amin; OPA tạo dẫn xuất huỳnh quang để phân tích."]}, {"title": "Cấu trúc và tính chất protein", "from": 35, "to": 61, "points": ["Bậc 1: thành phần và trình tự axit amin; bậc 2: xoắn α hoặc gấp β được ổn định bởi liên kết hydro.", "Bậc 3 là cấu trúc không gian; bậc 4 là sự sắp xếp nhiều đơn vị cấu trúc bậc 3.", "Tại pH = pI, protein trung hòa điện và có độ tan thấp; khi pH khác pI, điện tích và độ tan thay đổi.", "Muối nồng độ cao có thể gây salting out. Biến tính làm thay đổi cấu trúc bậc cao và hoạt tính.", "Protein hấp thụ ở 280 nm nhờ axit amin thơm; phản ứng Biuret liên quan liên kết peptide và tạo phức màu tím."]}, {"title": "Vai trò và phân loại", "from": 62, "to": 75, "points": ["Protein có chức năng xúc tác, vận chuyển, bảo vệ, điều hòa và cấu trúc.", "Protein đơn giản chỉ có axit amin; protein phức còn có phần phi protein.", "Phân biệt dạng sợi và dạng cầu; cấu trúc protein phù hợp với chức năng, môi trường tồn tại."]}, {"title": "Chuyển hóa axit amin", "from": 77, "to": 99, "points": ["Thoái hóa nhóm amin gồm trao đổi amin và khử amin oxy hóa; α-ketoglutarate là chất nhận amin phổ biến.", "Glutamate dehydrogenase xúc tác khử amin oxy hóa glutamate, dùng NAD⁺ hoặc NADP⁺.", "NH₃/NH₄⁺ được chuyển dưới dạng glutamine; chu trình ure diễn ra ở gan, gồm bước trong ti thể và bào tương.", "Decarboxylase loại nhóm carboxyl dưới dạng CO₂, tạo amin sinh học.", "PKU được trình bày liên quan thiếu phenylalanine hydroxylase."]}, {"title": "Protein máu", "from": 101, "to": 124, "points": ["Máu gồm tế bào máu và huyết tương; huyết thanh là phần dịch thu sau đông máu.", "Albumin tổng hợp ở gan, duy trì áp suất thẩm thấu và vận chuyển các chất kém hòa tan.", "Globulin miễn dịch là kháng thể; IgG có thể qua nhau thai, IgA có trong dịch tiết, IgM xuất hiện sớm trong đáp ứng được mô tả.", "Haptoglobin vận chuyển hemoglobin tự do; hemopexin vận chuyển hem; ceruloplasmin vận chuyển đồng; transferrin vận chuyển sắt.", "CRP liên quan quá trình viêm; cystatin C là chỉ thị đánh giá mức lọc cầu thận."]}, {"title": "Phân tích protein", "from": 125, "to": 146, "points": ["SDS-PAGE giúp phân tích các băng protein; SDS tạo điện tích âm, β-mercaptoethanol tác động lên cầu disulfide.", "Lowry dùng thuốc thử Folin–Ciocalteau; Bradford dùng Coomassie Brilliant Blue G-250, đo ở 595 nm.", "Kjeldahl xác định nitơ tổng số rồi quy đổi thành protein theo hệ số phù hợp.", "Sắc ký trao đổi ion dựa trên điện tích; lọc gel dựa trên kích thước; ái lực dựa trên tính gắn đặc hiệu."]}], "questions": [{"id": "s06-q001", "page": 4, "prompt": "Yếu tố nào quyết định nhiều đặc tính của một axit amin?", "options": ["Mạch bên R", "Chỉ số trang trong slide", "Thể tích mẫu", "Màu của đệm"], "answer": 0, "explanation": "Slide nhấn mạnh đặc tính axit amin phụ thuộc mạch bên R."}, {"id": "s06-q002", "page": 5, "prompt": "Axit amin trong tế bào động vật có vú chủ yếu ở dạng nào?", "options": ["L", "D", "Chỉ dạng vòng", "Không có cấu trúc lập thể"], "answer": 0, "explanation": "Slide ghi axit amin chủ yếu là dạng L."}, {"id": "s06-q003", "page": 13, "prompt": "Axit amin thiết yếu là loại nào?", "options": ["Cơ thể không thể tổng hợp được", "Chỉ có trong vi khuẩn", "Không tham gia protein", "Luôn không có nitơ"], "answer": 0, "explanation": "Tính thiết yếu được định nghĩa bằng khả năng tự tổng hợp của cơ thể."}, {"id": "s06-q004", "page": 16, "prompt": "Cặp chất nào là chất trung gian trong sinh tổng hợp arginine và chu trình ure?", "options": ["Ornithine và citrulline", "Glucose và fructose", "Cholesterol và glycerol", "Albumin và globulin"], "answer": 0, "explanation": "Slide giới thiệu ornithine và citrulline không thuộc các axit amin cấu tạo protein thông thường."}, {"id": "s06-q005", "page": 27, "prompt": "Liên kết peptide có nhóm liên kết nào?", "options": ["CO–NH", "S–S", "C–O–P trong mọi trường hợp", "Na–Cl"], "answer": 0, "explanation": "Slide minh họa liên kết CO–NH khi các axit amin liên kết."}, {"id": "s06-q006", "page": 28, "prompt": "Phản ứng nào được nêu để nhận biết axit amin?", "options": ["Ninhydrin", "Benedict", "Friedewald", "Xà phòng hóa"], "answer": 0, "explanation": "Slide gọi ninhydrin là phản ứng đặc trưng để nhận biết axit amin."}, {"id": "s06-q007", "page": 36, "prompt": "Cấu trúc bậc 1 mô tả điều gì?", "options": ["Thành phần và trình tự axit amin", "Sự sắp xếp nhiều tiểu đơn vị", "Chỉ dạng xoắn α", "Chỉ tương tác protein với lipid"], "answer": 0, "explanation": "Bậc 1 là chuỗi axit amin liên kết bằng liên kết peptide."}, {"id": "s06-q008", "page": 38, "prompt": "Cấu trúc xoắn α và gấp β được gia cố chủ yếu bởi liên kết nào?", "options": ["Hydro", "Glycosid", "Este", "Liên kết ion với NaCl duy nhất"], "answer": 0, "explanation": "Slide mô tả liên kết hydro ổn định cấu trúc bậc 2."}, {"id": "s06-q009", "page": 41, "prompt": "Cấu trúc bậc 4 được mô tả thế nào?", "options": ["Sắp xếp nhiều đơn vị protein bậc 3 thành phức hợp", "Chỉ trình tự axit amin", "Chỉ một liên kết peptide", "Chỉ một nhóm carboxyl"], "answer": 0, "explanation": "Bậc 4 liên quan sự kết hợp nhiều đơn vị protein."}, {"id": "s06-q010", "page": 45, "prompt": "Tại pH = pI, protein có đặc điểm nào?", "options": ["Trung hòa điện và độ tan kém nhất", "Luôn tích điện dương mạnh nhất", "Luôn tích điện âm mạnh nhất", "Luôn tan vô hạn"], "answer": 0, "explanation": "Slide liên hệ trạng thái đẳng điện với độ tan thấp."}, {"id": "s06-q011", "page": 46, "prompt": "Khi pH lớn hơn nhiều so với pI, protein thường mang điện gì?", "options": ["Âm", "Dương", "Luôn bằng không", "Không thể dự đoán từ pH và pI theo slide"], "answer": 0, "explanation": "Slide mô tả protein bị deproton hóa và mang điện tích âm."}, {"id": "s06-q012", "page": 51, "prompt": "Salting out xảy ra theo cơ chế nào được nêu?", "options": ["Muối nồng độ cao liên kết nước, làm protein có xu hướng kết tủa", "Muối biến protein thành glucose", "Muối làm mất toàn bộ nhóm amin", "Protein luôn tăng tan vô hạn khi thêm muối"], "answer": 0, "explanation": "Sự cạnh tranh tương tác với nước làm giảm hòa tan protein."}, {"id": "s06-q013", "page": 52, "prompt": "Biến tính protein chủ yếu liên quan sự thay đổi cấu trúc nào?", "options": ["Bậc 2, 3 và 4", "Chỉ số nguyên tử carbon trong mọi axit amin", "Chỉ công thức của nước", "Luôn cắt hết cấu trúc bậc 1"], "answer": 0, "explanation": "Slide định nghĩa biến tính bằng phá hủy một phần hoặc toàn bộ cấu trúc bậc cao."}, {"id": "s06-q014", "page": 59, "prompt": "Protein hấp thụ ở bước sóng 280 nm chủ yếu nhờ thành phần nào?", "options": ["Axit amin có mạch bên vòng thơm", "Chỉ ion natri", "Chỉ nước liên kết", "Chỉ glycerol"], "answer": 0, "explanation": "Slide liên hệ hấp thụ 280 nm với axit amin thơm."}, {"id": "s06-q015", "page": 60, "prompt": "Phản ứng Biuret tác động lên thành phần nào?", "options": ["Liên kết peptide", "Chỉ axit béo tự do", "Chỉ glucose tự do", "Chỉ cholesterol"], "answer": 0, "explanation": "Biuret tạo phức màu tím liên quan các liên kết peptide."}, {"id": "s06-q016", "page": 67, "prompt": "Protein đơn giản khác protein phức ở điểm nào?", "options": ["Chỉ gồm axit amin", "Bắt buộc có lipid", "Bắt buộc có đường", "Bắt buộc có kim loại"], "answer": 0, "explanation": "Slide phân loại homoprotein là loại chỉ gồm các axit amin."}, {"id": "s06-q017", "page": 80, "prompt": "Trao đổi amin giữa axit amin và keto acid tạo ra gì?", "options": ["Một keto acid và một axit amin mới", "Chỉ nước", "Chỉ lipid", "Hai phân tử cholesterol"], "answer": 0, "explanation": "Transaminase chuyển nhóm amin giữa hai bộ khung carbon."}, {"id": "s06-q018", "page": 81, "prompt": "Chất nhận nhóm amin phổ biến được nêu trong slide là gì?", "options": ["α-Ketoglutarate", "Cholesterol", "Sucrose", "Ure"], "answer": 0, "explanation": "α-Ketoglutarate nhận nhóm amin để trở thành glutamate."}, {"id": "s06-q019", "page": 86, "prompt": "Enzym nào xúc tác khử amin oxy hóa glutamate?", "options": ["Glutamate dehydrogenase", "Lipase", "Amylase", "Trypsin"], "answer": 0, "explanation": "Slide nêu GLDH với coenzym NAD⁺ hoặc NADP⁺."}, {"id": "s06-q020", "page": 88, "prompt": "NH₃/NH₄⁺ có thể được gắn vào glutamate để tạo chất vận chuyển nào?", "options": ["Glutamine", "Glycogen", "Cholesterol", "Albumin"], "answer": 0, "explanation": "Slide mô tả glutamine theo máu tới gan, thận."}, {"id": "s06-q021", "page": 89, "prompt": "Chu trình ure diễn ra ở cơ quan nào?", "options": ["Gan", "Phổi", "Da", "Tuyến nước bọt"], "answer": 0, "explanation": "Slide nêu chu trình ure ở gan với các bước trong ti thể và bào tương."}, {"id": "s06-q022", "page": 93, "prompt": "Decarboxylase tác động lên axit amin tạo nhóm sản phẩm nào?", "options": ["Amin sinh học và CO₂", "Chỉ triglyceride", "Chỉ glycogen", "Chỉ phosphate vô cơ"], "answer": 0, "explanation": "Phản ứng loại nhóm carboxyl dưới dạng CO₂ tạo amin sinh học."}, {"id": "s06-q023", "page": 97, "prompt": "PKU được liên hệ với sự thiếu hụt enzym nào?", "options": ["Phenylalanine hydroxylase", "Amylase", "Lipoprotein lipase", "Catalase"], "answer": 0, "explanation": "Slide mô tả rối loạn chuyển phenylalanine thành tyrosine do thiếu enzym này."}, {"id": "s06-q024", "page": 103, "prompt": "Huyết thanh được mô tả là gì?", "options": ["Phần dịch thu sau khi máu đông", "Toàn bộ các hồng cầu", "Máu chưa tách tế bào", "Chỉ phần protein đã kết tủa"], "answer": 0, "explanation": "Slide phân biệt huyết thanh với huyết tương và tế bào máu."}, {"id": "s06-q025", "page": 109, "prompt": "Albumin được tổng hợp ở đâu?", "options": ["Gan", "Tuyến nước bọt", "Phổi", "Bàng quang"], "answer": 0, "explanation": "Slide nêu albumin tổng hợp ở gan."}, {"id": "s06-q026", "page": 109, "prompt": "Vai trò nào của albumin được nêu trong slide?", "options": ["Duy trì áp suất thẩm thấu và vận chuyển chất kém hòa tan", "Chỉ cắt liên kết peptide", "Chỉ tạo glucose từ tinh bột", "Chỉ tạo kháng nguyên ABO"], "answer": 0, "explanation": "Albumin giữ vai trò về áp suất thẩm thấu và vận chuyển nhiều chất."}, {"id": "s06-q027", "page": 115, "prompt": "Kháng thể nào được mẹ truyền sang trẻ qua nhau thai?", "options": ["IgG", "IgM", "IgA", "IgE"], "answer": 0, "explanation": "Slide ghi IgG của trẻ sơ sinh có thể có nguồn từ mẹ qua nhau thai."}, {"id": "s06-q028", "page": 115, "prompt": "Kháng thể nào được nêu có trong nước bọt, nước mắt và dịch ruột?", "options": ["IgA", "IgD", "IgE", "Chỉ IgM"], "answer": 0, "explanation": "IgA được trình bày gắn với bảo vệ bề mặt và các dịch tiết."}, {"id": "s06-q029", "page": 119, "prompt": "Haptoglobin gắn và vận chuyển thành phần nào?", "options": ["Hemoglobin tự do", "Chỉ cholesterol ester", "Chỉ phosphate", "Chỉ glucose"], "answer": 0, "explanation": "Haptoglobin gắn hemoglobin tự do để đưa tới khu vực thoái hóa."}, {"id": "s06-q030", "page": 120, "prompt": "Ceruloplasmin có chức năng vận chuyển kim loại nào?", "options": ["Đồng", "Natri", "Kali", "Magnesi"], "answer": 0, "explanation": "Slide nêu ceruloplasmin vận chuyển đồng trong huyết tương."}, {"id": "s06-q031", "page": 121, "prompt": "Transferrin vận chuyển chất nào tới tủy xương để tổng hợp hồng cầu?", "options": ["Sắt", "Glucose", "Ure", "Chloride"], "answer": 0, "explanation": "Transferrin là glycoprotein vận chuyển sắt theo phần mô tả."}, {"id": "s06-q032", "page": 122, "prompt": "Cystatin C được dùng làm chỉ thị đánh giá điều gì?", "options": ["Mức lọc cầu thận", "Chỉ nhóm máu ABO", "Chỉ độ ngọt của đường", "Chỉ tốc độ đông đặc lipid"], "answer": 0, "explanation": "Slide liên hệ cystatin C với đánh giá mức độ lọc ở cầu thận."}, {"id": "s06-q033", "page": 129, "prompt": "Trong SDS-PAGE, protein tích điện âm đi về phía nào?", "options": ["Cực dương, anode", "Cực âm, cathode", "Luôn đứng yên tại giếng", "Ngược mọi điện trường"], "answer": 0, "explanation": "Slide nêu protein di chuyển từ cathode sang anode."}, {"id": "s06-q034", "page": 139, "prompt": "Phương pháp Bradford đo phức protein–Coomassie ở bước sóng nào?", "options": ["595 nm", "280 nm", "405 nm", "340 nm"], "answer": 0, "explanation": "Slide ghi λmax của phức Coomassie–protein là 595 nm."}, {"id": "s06-q035", "page": 143, "prompt": "Kjeldahl trực tiếp xác định đại lượng nào trước khi quy đổi thành protein?", "options": ["Nitơ tổng số", "Số liên kết disulfide", "Số tiểu đơn vị protein", "Cholesterol toàn phần"], "answer": 0, "explanation": "Cần hệ số quy đổi vì Kjeldahl đo nitơ tổng số."}, {"id": "s06-q036", "page": 145, "prompt": "Trong sắc ký lọc gel theo slide, protein lớn di chuyển thế nào so với protein nhỏ?", "options": ["Nhanh hơn vì ít đi vào lỗ gel", "Chậm hơn vì luôn đi vào mọi lỗ gel", "Không thể di chuyển", "Luôn có cùng tốc độ"], "answer": 0, "explanation": "Protein nhỏ đi vào lỗ gel nên theo đường dài hơn và bị làm chậm."}], "source": {"file": "4. Axit Amin - PROTEN huyet thanh.pdf", "url": "sources/s06.pdf", "pages": 146, "sha256": "ca0902f20767379656e1252d91d7a5852f31703cdf5bebdba72229dfcdb5fd99"}}, {"id": "s07", "title": "Lipid · Cấu trúc và chuyển hóa", "group": "Lipid", "description": "Axit béo, lipoprotein, β-oxy hóa, tổng hợp và rối loạn lipid.", "sections": [{"title": "Cấu tạo và phân loại", "from": 3, "to": 25, "points": ["Lipid ít tan hoặc không tan trong nước, tan trong các dung môi không phân cực được nêu trong slide.", "Phân loại theo khả năng xà phòng hóa, cấu tạo hoặc chức năng.", "Ký hiệu Cx:y mô tả số carbon và số nối đôi; hệ Δ tính từ đầu COOH, hệ omega tính từ đầu CH₃.", "Theo bài, axit béo thiết yếu không được cơ thể tổng hợp và phải cung cấp từ thức ăn; slide nhấn mạnh linoleic, linolenic.", "Cholesterol là sterol quan trọng, tiền chất của hormon và muối mật."]}, {"title": "Lipid đơn giản và phức tạp", "from": 26, "to": 50, "points": ["Glycerit chứa glycerol và axit béo; sáp là este của axit béo với alcohol mạch dài; sterit chứa sterol.", "Lipase thủy phân glycerit; phản ứng xà phòng hóa liên quan liên kết este.", "Halogen cộng vào nối đôi; chỉ số iod liên quan mức độ không no.", "Phospholipid chứa phosphate, glycolipid chứa đường; chúng được trình bày gắn với cấu trúc màng."]}, {"title": "Lipoprotein và vận chuyển", "from": 51, "to": 74, "points": ["Lipoprotein có lõi TAG, cholesterol ester; vỏ gồm phospholipid, apoprotein và cholesterol.", "Chylomicron vận chuyển lipid ngoại sinh; VLDL vận chuyển TAG nội sinh; LDL cung cấp cholesterol cho mô; HDL vận chuyển ngược cholesterol về gan.", "Chylomicron hình thành với ApoB-48; VLDL và LDL liên quan ApoB-100.", "ApoC-II hoạt hóa LPL; ApoE hỗ trợ nhận diện phần tử tàn dư ở gan; ApoA-I hoạt hóa LCAT.", "VLDL mất TAG thành IDL; IDL được gan thu nhận hoặc tiếp tục thành LDL."]}, {"title": "β-oxy hóa", "from": 75, "to": 84, "points": ["Quá trình gồm hoạt hóa, vận chuyển vào ti thể và β-oxy hóa.", "Bốn phản ứng mỗi vòng: khử H lần 1, thêm nước, khử H lần 2 và phân cắt.", "Mỗi vòng tạo FADH₂, NADH, acetyl-CoA và làm ngắn mạch đi hai carbon.", "Với axit béo no mạch chẵn 2n carbon, bài nêu n−1 vòng, n acetyl-CoA và năng lượng ròng 14n−6 ATP.", "Mạch lẻ tạo propionyl-CoA, tiếp tục chuyển thành succinyl-CoA."]}, {"title": "Tổng hợp lipid", "from": 85, "to": 99, "points": ["Tổng hợp axit béo diễn ra khi dư năng lượng, chủ yếu trong bào tương ở gan, mô mỡ và niêm mạc ruột.", "Citrate đưa đơn vị acetyl từ ti thể ra bào tương; acetyl-CoA carboxylase tạo malonyl-CoA.", "FAS kéo dài mạch; mỗi vòng gắn thêm malonyl cần 2 NADPH.", "Tổng hợp triglyceride qua glycerol-3-phosphate và phosphatidic acid; cholesterol có nguồn carbon từ acetyl-CoA."]}, {"title": "Rối loạn lipid máu", "from": 100, "to": 113, "points": ["Slide phân biệt yếu tố di truyền với ảnh hưởng lối sống, bệnh lý, thuốc và hormon.", "Type IIa: tăng cholesterol và LDL; IIb: tăng LDL và VLDL; III: tăng IDL; IV: tăng VLDL và triglyceride.", "Type I/V có thể liên quan bất thường LPL hoặc ApoC-II và chậm thoái hóa chylomicron.", "Các mô tả rối loạn được dùng làm kiến thức ôn tập đúng nội dung bài."]}], "questions": [{"id": "s07-q001", "page": 3, "prompt": "Đặc tính hòa tan chung của lipid trong slide là gì?", "options": ["Ít tan trong nước, tan tốt trong dung môi không phân cực", "Tan hoàn toàn trong mọi dung môi", "Chỉ tan trong nước", "Không tan trong bất kỳ dung môi nào"], "answer": 0, "explanation": "Độ hòa tan là đặc điểm chung được dùng trong định nghĩa lipid."}, {"id": "s07-q002", "page": 5, "prompt": "Theo slide, lipid xà phòng hóa được có đặc điểm gì?", "options": ["Có liên kết este", "Không có liên kết este", "Chỉ có ion natri", "Chỉ có liên kết peptide"], "answer": 0, "explanation": "Phân loại theo xà phòng hóa dựa trên sự có mặt của liên kết este."}, {"id": "s07-q003", "page": 7, "prompt": "Lipid phức tạp nào có chứa nhóm đường?", "options": ["Glycolipid", "Sáp", "Sterit", "Glycerit đơn giản"], "answer": 0, "explanation": "Slide phân biệt glycolipid chứa gluxit với phospholipid và lipoprotein."}, {"id": "s07-q004", "page": 11, "prompt": "Axit béo no khác axit béo không no ở điểm nào?", "options": ["Chỉ có nối đơn trong mạch carbon", "Có ít nhất ba nối đôi", "Luôn có mạch vòng", "Không có nhóm COOH"], "answer": 0, "explanation": "Slide phân biệt no và không no bằng sự có mặt của nối đôi."}, {"id": "s07-q005", "page": 13, "prompt": "Trong ký hiệu C18:2, số 2 biểu thị điều gì?", "options": ["Số nối đôi", "Số nguyên tử oxy", "Số nhóm COOH", "Số phân tử alcohol"], "answer": 0, "explanation": "Công thức Cx:y dùng x là số carbon, y là số nối đôi."}, {"id": "s07-q006", "page": 13, "prompt": "Vị trí omega của axit béo được tính từ đầu nào?", "options": ["Đầu CH₃ cuối mạch", "Đầu COOH", "Carbon α của mọi nhóm OH", "Nguyên tử oxy của nước"], "answer": 0, "explanation": "Slide quy ước carbon cuối CH₃ là Cω."}, {"id": "s07-q007", "page": 20, "prompt": "Axit béo nào được gọi là bán thiết yếu vì có thể tổng hợp từ linoleic?", "options": ["Arachidonic", "Palmitic", "Stearic", "Oleic"], "answer": 0, "explanation": "Slide nêu arachidonic có thể được tổng hợp từ linoleic."}, {"id": "s07-q008", "page": 22, "prompt": "Alcohol mạch vòng nào được nêu thuộc nhóm sterol?", "options": ["Cholesterol", "Glycerol", "Methanol", "Ethanol"], "answer": 0, "explanation": "Cholesterol là ví dụ sterol trong phần các alcohol của lipid."}, {"id": "s07-q009", "page": 25, "prompt": "Cholesterol là tiền chất của nhóm chất nào được nêu trong slide?", "options": ["Hormon giới tính và muối mật", "Chỉ các kháng thể", "Chỉ glycogen", "Chỉ axit amin thiết yếu"], "answer": 0, "explanation": "Slide trình bày cholesterol là tiền chất của androgen, estrogen và muối mật."}, {"id": "s07-q010", "page": 30, "prompt": "Enzym nào được nêu trong sự thủy phân glycerit?", "options": ["Lipase", "Amylase", "Transaminase", "Urease"], "answer": 0, "explanation": "Lipase xúc tác thủy phân lipid theo phần tính chất hóa học."}, {"id": "s07-q011", "page": 34, "prompt": "Chỉ số iod liên quan đến đặc điểm nào của chất béo?", "options": ["Mức độ không no của mạch carbon", "Số liên kết peptide", "Hàm lượng nitơ tổng số", "Khối lượng albumin"], "answer": 0, "explanation": "Halogen phản ứng tại nối đôi nên chỉ số iod phản ánh đặc điểm không no."}, {"id": "s07-q012", "page": 36, "prompt": "Hydrogen hóa tác động chủ yếu lên vị trí nào của axit béo?", "options": ["Liên kết đôi", "Chỉ nhóm amin", "Chỉ liên kết peptide", "Chỉ phân tử nước"], "answer": 0, "explanation": "Quá trình gắn H₂ vào liên kết đôi làm tăng mức độ bão hòa."}, {"id": "s07-q013", "page": 39, "prompt": "Muối mật hỗ trợ tiêu hóa chất béo bằng cách nào?", "options": ["Nhũ hóa để chất béo dễ được lipase phân giải", "Biến lipid thành protein trực tiếp", "Chỉ vận chuyển sắt", "Ngăn mọi hoạt động của lipase"], "answer": 0, "explanation": "Slide nêu vai trò nhũ hóa của dẫn xuất cholesterol là muối mật."}, {"id": "s07-q014", "page": 52, "prompt": "Lõi không phân cực của lipoprotein chứa chủ yếu gì?", "options": ["TAG và cholesterol ester", "Chỉ nước và NaCl", "Chỉ protein và glucose", "Chỉ phosphate tự do"], "answer": 0, "explanation": "Cấu trúc lõi được phân biệt với vỏ phospholipid, apoprotein và cholesterol."}, {"id": "s07-q015", "page": 54, "prompt": "ApoB-48 được nêu có trong loại lipoprotein nào?", "options": ["Chylomicron", "Chỉ LDL", "Chỉ HDL", "Chỉ IDL"], "answer": 0, "explanation": "ApoB-48 liên quan vận chuyển lipid từ ruột trong chylomicron."}, {"id": "s07-q016", "page": 56, "prompt": "Lipoprotein nào vận chuyển chủ yếu cholesterol từ mô về gan?", "options": ["HDL", "LDL", "VLDL", "Chylomicron"], "answer": 0, "explanation": "HDL đảm nhiệm vận chuyển ngược cholesterol theo mô tả của slide."}, {"id": "s07-q017", "page": 58, "prompt": "Trong bốn loại ở bảng, loại nào có tỷ trọng nhỏ nhất, kích thước lớn nhất?", "options": ["Chylomicron", "HDL", "LDL", "VLDL"], "answer": 0, "explanation": "Bảng so sánh nêu rõ đặc điểm này của chylomicron."}, {"id": "s07-q018", "page": 65, "prompt": "Chylomicron mới tạo được giải phóng theo đường nào trước khi vào máu?", "options": ["Hệ bạch huyết", "Ống mật", "Khí quản", "Ống niệu quản"], "answer": 0, "explanation": "Slide mô tả chylomicron từ tế bào ruột vào bạch huyết rồi vào máu."}, {"id": "s07-q019", "page": 66, "prompt": "ApoC-II có vai trò gì trong chuyển hóa chylomicron?", "options": ["Kích hoạt lipoprotein lipase", "Trực tiếp tạo hemoglobin", "Ức chế mọi hấp thu lipid", "Tạo liên kết peptide"], "answer": 0, "explanation": "ApoC-II hoạt hóa LPL để thủy phân triglyceride."}, {"id": "s07-q020", "page": 67, "prompt": "ApoE trên chylomicron tàn dư hỗ trợ quá trình nào?", "options": ["Gắn vào thụ thể ở tế bào gan", "Tạo glucose từ CO₂ trực tiếp", "Tổng hợp kháng thể IgG", "Vận chuyển oxy trong hồng cầu"], "answer": 0, "explanation": "ApoE giúp gan nhận diện, thu nhận và phân giải chylomicron tàn dư."}, {"id": "s07-q021", "page": 70, "prompt": "VLDL được tổng hợp chủ yếu ở đâu?", "options": ["Gan", "Phổi", "Tuyến nước bọt", "Da"], "answer": 0, "explanation": "Slide mô tả gan tổng hợp VLDL để vận chuyển lipid nội sinh."}, {"id": "s07-q022", "page": 71, "prompt": "VLDL mất phần lớn triglyceride sẽ chuyển thành gì?", "options": ["IDL", "Albumin", "Chylomicron mới", "IgM"], "answer": 0, "explanation": "LPL thủy phân TAG làm VLDL trở thành IDL."}, {"id": "s07-q023", "page": 72, "prompt": "Một hướng chuyển hóa tiếp theo của IDL là gì?", "options": ["Tiếp tục mất triglyceride để thành LDL", "Biến thành glucose tự do hoàn toàn", "Chuyển trực tiếp thành hemoglobin", "Trở lại tế bào ruột trong mọi trường hợp"], "answer": 0, "explanation": "IDL có thể được gan thu nhận hoặc tiếp tục chuyển thành LDL."}, {"id": "s07-q024", "page": 74, "prompt": "ApoA-I của HDL hoạt hóa enzym nào?", "options": ["LCAT", "Trypsin", "Urease", "Amylase"], "answer": 0, "explanation": "LCAT ester hóa cholesterol, góp phần hình thành HDL trưởng thành."}, {"id": "s07-q025", "page": 75, "prompt": "Thứ tự ba giai đoạn chuyển hóa axit béo được nêu là gì?", "options": ["Hoạt hóa → vận chuyển vào ti thể → β-oxy hóa", "β-oxy hóa → hoạt hóa → vận chuyển", "Vận chuyển → tạo glycogen → hoạt hóa", "Thủy phân protein → tạo ure → β-oxy hóa"], "answer": 0, "explanation": "Slide nêu ba giai đoạn theo đúng thứ tự này."}, {"id": "s07-q026", "page": 77, "prompt": "Chất nào hỗ trợ vận chuyển axit béo đã hoạt hóa vào ti thể?", "options": ["Carnitine", "Albumin", "IgE", "Sucrose"], "answer": 0, "explanation": "Trang vận chuyển vào ti thể minh họa vai trò carnitine."}, {"id": "s07-q027", "page": 78, "prompt": "Phản ứng khử H lần đầu của β-oxy hóa tạo chất mang điện tử nào?", "options": ["FADH₂", "NADPH", "ATP trực tiếp", "GTP trực tiếp"], "answer": 0, "explanation": "Acyl-CoA dehydrogenase xúc tác phản ứng đầu tạo FADH₂."}, {"id": "s07-q028", "page": 78, "prompt": "Sau một vòng β-oxy hóa, mạch acyl ngắn đi bao nhiêu carbon?", "options": ["2", "1", "3", "6"], "answer": 0, "explanation": "Slide nêu tạo một acetyl-CoA và mạch axit béo giảm hai carbon."}, {"id": "s07-q029", "page": 80, "prompt": "Propionyl-CoA từ axit béo mạch lẻ được chuyển thành chất nào để vào Krebs?", "options": ["Succinyl-CoA", "Cholesterol", "Lactose", "Albumin"], "answer": 0, "explanation": "Slide trình bày con đường propionyl-CoA thành succinyl-CoA."}, {"id": "s07-q030", "page": 83, "prompt": "Theo công thức của slide, axit béo no C16 cần bao nhiêu vòng β-oxy hóa?", "options": ["7", "8", "15", "16"], "answer": 0, "explanation": "Với 2n = 16, n = 8; số vòng là n−1 = 7."}, {"id": "s07-q031", "page": 83, "prompt": "Theo cách tính của slide, oxy hóa hoàn toàn axit béo no C16 thu ròng bao nhiêu ATP?", "options": ["106", "112", "108", "96"], "answer": 0, "explanation": "Công thức ròng 14n−6, với n = 8 cho 106 ATP."}, {"id": "s07-q032", "page": 86, "prompt": "Tổng hợp axit béo trong bài được nêu diễn ra chủ yếu ở khoang nào?", "options": ["Bào tương", "Chỉ lòng lysosome", "Chỉ nhân tế bào", "Chỉ dịch ngoài tế bào"], "answer": 0, "explanation": "Slide nêu quá trình tại bào tương của các mô như gan và mô mỡ."}, {"id": "s07-q033", "page": 90, "prompt": "Đơn vị acetyl được đưa từ ti thể ra bào tương thông qua dạng nào?", "options": ["Citrate", "Ure", "Lactose", "Bilirubin"], "answer": 0, "explanation": "Acetyl-CoA kết hợp oxaloacetate tạo citrate, rồi tái tạo acetyl-CoA ở bào tương."}, {"id": "s07-q034", "page": 91, "prompt": "Enzym tạo malonyl-CoA từ acetyl-CoA là gì?", "options": ["Acetyl-CoA carboxylase", "Lipoprotein lipase", "Glucose oxidase", "Trypsin"], "answer": 0, "explanation": "Slide mô tả phản ứng kết hợp CO₂ do acetyl-CoA carboxylase xúc tác."}, {"id": "s07-q035", "page": 92, "prompt": "Mỗi vòng gắn thêm malonyl-CoA trong tổng hợp axit béo cần bao nhiêu NADPH?", "options": ["2", "1", "4", "8"], "answer": 0, "explanation": "Slide ghi mỗi vòng cần 2 NADPH."}, {"id": "s07-q036", "page": 96, "prompt": "Chất trung gian nào hình thành sau khi gắn acyl thứ hai trong tổng hợp triglyceride?", "options": ["Phosphatidic acid", "Cholesterol", "Glucose-6-phosphate", "Ure"], "answer": 0, "explanation": "Từ lysophosphatidic acid, gắn acyl thứ hai tạo phosphatidic acid."}, {"id": "s07-q037", "page": 109, "prompt": "Rối loạn lipid type IIa được slide mô tả bởi sự tăng nào?", "options": ["Cholesterol và LDL-C", "Chỉ HDL-C", "Chỉ glucose", "Chỉ albumin"], "answer": 0, "explanation": "Trang type IIa nêu tăng cholesterol đơn thuần, LDL-C tăng."}, {"id": "s07-q038", "page": 111, "prompt": "Rối loạn type III được liên hệ với apoprotein nào?", "options": ["ApoE", "ApoA-I", "Albumin", "Hemoglobin"], "answer": 0, "explanation": "Slide liên hệ type III với đột biến ApoE và giảm loại bỏ các phần tử tàn dư."}], "source": {"file": "5. Lipid.pdf", "url": "sources/s07.pdf", "pages": 113, "sha256": "c9f2ee8575fdb4b405e78b2e39b4687cded124769adf0894da79174351a4ee04"}}, {"id": "s08", "title": "Nước–khoáng và trao đổi muối nước", "group": "Nước–khoáng", "description": "Dung dịch đệm, điện giải, điều hòa nước và phần phân tích lipid cuối file.", "sections": [{"title": "Nước và dung dịch đệm", "from": 3, "to": 18, "points": ["Nước hòa tan muối và chất tích điện nhờ tương tác tĩnh điện.", "Axit yếu phân ly không hoàn toàn; hằng số Ka mô tả mức độ phân ly.", "Dung dịch đệm hạn chế thay đổi pH khi thêm lượng nhỏ axit hoặc base; pH ảnh hưởng cấu trúc, chức năng phân tử sinh học.", "Slide nêu các hệ đệm phosphate, bicarbonate và axit amin."]}, {"title": "Nước và chất vô cơ trong cơ thể", "from": 19, "to": 33, "points": ["Nước tham gia cấu tạo, phản ứng sinh hóa, vận chuyển, điều hòa nhiệt và bảo vệ.", "Na⁺ là cation chủ yếu ngoài tế bào; K⁺ chủ yếu trong tế bào; Cl⁻ là anion chính ngoài tế bào.", "HCO₃⁻ tham gia đệm và vận chuyển CO₂; phần lớn calcium và phosphate được nêu nằm trong xương.", "Giá trị và tỷ lệ trong bài được học theo chính slide, với điều kiện và đơn vị đi kèm."]}, {"title": "Trao đổi và điều hòa", "from": 34, "to": 44, "points": ["Phân bố nước chịu ảnh hưởng áp suất thẩm thấu, áp lực thủy tĩnh, màng, cân bằng Donnan và áp suất keo.", "Áp suất keo do protein tạo nên; vùng nhiều chất hòa tan có xu hướng hút nước.", "Mỗi ATP của bơm Na⁺/K⁺-ATPase đưa 3 Na⁺ ra ngoài, 2 K⁺ vào trong.", "ADH tăng tái hấp thu nước; aldosteron tăng tái hấp thu Na⁺; ANP thúc đẩy bài tiết Na⁺ và nước."]}, {"title": "Rối loạn nước–điện giải", "from": 45, "to": 50, "points": ["Mất nước là lượng mất vượt lượng vào; ứ nước liên quan dư thừa nước.", "Slide nêu hạ Na⁺ dưới 135 mmol/L và tăng Na⁺ trên 145 mmol/L.", "Hạ K⁺ dưới 3,5 mmol/L; tăng K⁺ trên 5,0 mmol/L theo slide.", "Bài yêu cầu phối hợp thông số điện giải, huyết tương, nước tiểu và bối cảnh để đánh giá rối loạn."]}, {"title": "Phần cuối file: phân tích lipid máu", "from": 51, "to": 56, "points": ["Trang 51–56 của PDF này chuyển sang phân tích triglyceride, cholesterol và HDL-C.", "Phép triglyceride dùng chuỗi enzym và phản ứng hiện màu; phép cholesterol trong slide đo ở 500 nm.", "Định lượng HDL-C: kết tủa các lipoprotein còn lại bằng phosphotungstic acid và Mg²⁺, ly tâm rồi đo phần HDL.", "Câu hỏi phần này giữ nguồn ở PDF Nước–khoáng đúng vị trí tài liệu."]}], "questions": [{"id": "s08-q001", "page": 5, "prompt": "Nước hòa tan muối và hợp chất tích điện nhờ tương tác nào?", "options": ["Tĩnh điện", "Chỉ liên kết peptide", "Chỉ liên kết glycosid", "Chỉ cầu disulfide"], "answer": 0, "explanation": "Slide nêu các tương tác tĩnh điện giải thích khả năng hòa tan này."}, {"id": "s08-q002", "page": 12, "prompt": "Ở trạng thái trung tính, quan hệ giữa H⁺ và OH⁻ là gì?", "options": ["Nồng độ H⁺ bằng nồng độ OH⁻", "H⁺ luôn gấp 100 lần OH⁻", "OH⁻ luôn bằng không", "H⁺ luôn bằng 1 mol/L"], "answer": 0, "explanation": "Slide mô tả trung tính bằng sự bằng nhau của hai nồng độ."}, {"id": "s08-q003", "page": 14, "prompt": "Axit yếu trong nước có đặc điểm gì?", "options": ["Phân ly không hoàn toàn", "Luôn phân ly hoàn toàn", "Không bao giờ có H⁺", "Luôn tạo protein"], "answer": 0, "explanation": "Mức độ phân ly của axit yếu được thể hiện bằng Ka."}, {"id": "s08-q004", "page": 16, "prompt": "Đặc điểm của vùng đệm khi chuẩn độ là gì?", "options": ["pH thay đổi không đáng kể khi thêm lượng nhỏ hóa chất chuẩn độ", "pH luôn tăng đúng 7 đơn vị", "pH đổi tối đa ngay khi thêm một giọt", "Dung dịch không còn nước"], "answer": 0, "explanation": "Khả năng hạn chế biến đổi pH là đặc điểm của vùng đệm."}, {"id": "s08-q005", "page": 18, "prompt": "Theo bảng vùng đệm trong slide, acetate dùng ở khoảng pH nào?", "options": ["4–5", "1–2", "8–10", "12–14"], "answer": 0, "explanation": "Slide nêu acetate 4–5, phosphate 6–7 và borat 8–10."}, {"id": "s08-q006", "page": 23, "prompt": "Vai trò điều hòa thân nhiệt của nước được minh họa qua quá trình nào?", "options": ["Mồ hôi và hơi thở", "Chỉ tổng hợp glycogen", "Chỉ tổng hợp cholesterol", "Chỉ tạo kháng thể"], "answer": 0, "explanation": "Nước tham gia điều hòa thân nhiệt qua mồ hôi và hơi thở theo slide."}, {"id": "s08-q007", "page": 24, "prompt": "Nhóm nào được nêu là các chất vô cơ có hàm lượng lớn trong cơ thể?", "options": ["Na, K, Cl, Ca, P, Mg", "Chỉ Cr, Si, Ti", "Chỉ Cu, Zn, iod", "Chỉ carbon của glucose"], "answer": 0, "explanation": "Slide phân biệt nhóm hàm lượng lớn với vi lượng và siêu vi lượng."}, {"id": "s08-q008", "page": 28, "prompt": "Cation chủ yếu ngoài tế bào được nêu là gì?", "options": ["Na⁺", "K⁺", "Fe²⁺", "Zn²⁺"], "answer": 0, "explanation": "Slide nêu Na⁺ chiếm 90% tổng cation ngoại bào."}, {"id": "s08-q009", "page": 29, "prompt": "K⁺ trong cơ thể tồn tại chủ yếu ở đâu?", "options": ["Trong tế bào", "Chỉ trong huyết tương", "Chỉ trong dịch gian bào", "Chỉ trong dịch mật"], "answer": 0, "explanation": "Slide ghi 98% K⁺ ở trong tế bào, 2% ngoài tế bào."}, {"id": "s08-q010", "page": 30, "prompt": "Anion chính của dịch ngoài tế bào là gì?", "options": ["Cl⁻", "Chỉ PO₄³⁻", "Chỉ SO₄²⁻", "Chỉ lactate"], "answer": 0, "explanation": "Slide nêu chloride là anion chính ngoài tế bào."}, {"id": "s08-q011", "page": 31, "prompt": "HCO₃⁻ có vai trò nào được trình bày?", "options": ["Tham gia hệ đệm và vận chuyển CO₂", "Chỉ vận chuyển oxy bằng heme", "Chỉ cấu tạo kháng thể", "Chỉ thủy phân protein"], "answer": 0, "explanation": "Bicarbonate gắn với cân bằng acid–base và vận chuyển CO₂ về phổi."}, {"id": "s08-q012", "page": 32, "prompt": "Theo slide, khoảng bao nhiêu calcium của cơ thể nằm trong xương?", "options": ["99%", "1%", "25%", "50%"], "answer": 0, "explanation": "Trang calcium nêu 99% trong xương."}, {"id": "s08-q013", "page": 37, "prompt": "Áp suất keo được tạo ra bởi thành phần nào?", "options": ["Protein", "Chỉ glucose", "Chỉ NaCl", "Chỉ ure"], "answer": 0, "explanation": "Slide phân biệt áp suất keo do protein với các đóng góp thẩm thấu khác."}, {"id": "s08-q014", "page": 37, "prompt": "Khu vực có áp suất thẩm thấu cao có xu hướng nào?", "options": ["Hút nước vào khu vực đó", "Luôn đẩy nước ra khỏi khu vực đó", "Không có chất hòa tan", "Không liên quan nước"], "answer": 0, "explanation": "Nồng độ chất hòa tan lớn tạo xu hướng hút nước theo mô tả của slide."}, {"id": "s08-q015", "page": 38, "prompt": "Áp lực thủy tĩnh có xu hướng tác động lên nước như thế nào?", "options": ["Đẩy nước ra xa khu vực áp suất cao", "Luôn hút nước vào khu vực áp suất cao", "Chỉ làm biến tính enzym", "Chỉ đổi nồng độ hemoglobin"], "answer": 0, "explanation": "Slide mô tả áp lực thủy tĩnh đẩy nước để giảm áp."}, {"id": "s08-q016", "page": 39, "prompt": "Một điều kiện của cân bằng Donnan được nêu là gì?", "options": ["Tổng điện tích dương bằng tổng điện tích âm ở mỗi phía màng", "Mọi ion phải biến mất", "Hai phía không được có nước", "Mọi phân tử protein phải qua màng"], "answer": 0, "explanation": "Định luật Donnan thứ hai trong slide là điều kiện trung hòa điện mỗi phía."}, {"id": "s08-q017", "page": 41, "prompt": "Một ATP của bơm Na⁺/K⁺-ATPase vận chuyển thế nào?", "options": ["3 Na⁺ ra ngoài và 2 K⁺ vào trong", "2 Na⁺ ra ngoài và 3 K⁺ vào trong", "3 Na⁺ vào trong và 2 K⁺ ra ngoài", "1 Na⁺ và 1 K⁺ cùng ra ngoài"], "answer": 0, "explanation": "Slide ghi rõ tỷ lệ vận chuyển 3 Na⁺/2 K⁺ cho một ATP."}, {"id": "s08-q018", "page": 42, "prompt": "Khi áp suất thẩm thấu tăng 1–2%, phản ứng được nêu là gì?", "options": ["Kích thích bài tiết ADH", "Luôn ngừng tạo ADH", "Ngừng hoàn toàn cảm giác khát", "Loại bỏ toàn bộ K⁺ nội bào"], "answer": 0, "explanation": "Slide mô tả đáp ứng cảm nhận thẩm thấu kích thích ADH."}, {"id": "s08-q019", "page": 43, "prompt": "ADH giảm sẽ dẫn tới thay đổi nào được nêu?", "options": ["Giảm tái hấp thu nước ở thận", "Tăng tái hấp thu nước ở mọi mức", "Không còn nước tiểu", "Tăng tổng hợp albumin trực tiếp"], "answer": 0, "explanation": "ADH giảm làm nước bị đào thải qua đường tiểu nhiều hơn theo mô tả."}, {"id": "s08-q020", "page": 43, "prompt": "Aldosteron có tác động nào trong bài?", "options": ["Tăng tái hấp thu natri ở thận", "Giảm mọi tái hấp thu natri", "Chỉ vận chuyển oxy", "Chỉ tạo kháng thể"], "answer": 0, "explanation": "Aldosteron được nêu là hormon tăng tái hấp thu Na⁺."}, {"id": "s08-q021", "page": 43, "prompt": "ANP có tác động nào?", "options": ["Tăng bài tiết Na⁺ và nước", "Giữ lại mọi Na⁺ và nước", "Chỉ tăng tổng hợp ure", "Chỉ tăng phân giải hemoglobin"], "answer": 0, "explanation": "Slide mô tả ANP tăng lọc và giảm tái hấp thu Na⁺ ở thận."}, {"id": "s08-q022", "page": 46, "prompt": "Mất nước được định nghĩa như thế nào?", "options": ["Nước mất vượt quá lượng nước vào", "Lượng nước vào luôn nhiều hơn mất", "Chỉ có khi ngừng ăn", "Chỉ khi sodium bằng không"], "answer": 0, "explanation": "Định nghĩa trong slide dựa trên cân bằng vào–ra."}, {"id": "s08-q023", "page": 48, "prompt": "Theo ngưỡng trong slide, hạ Na⁺ máu là khi nào?", "options": ["Dưới 135 mmol/L", "Trên 145 mmol/L", "Trên 150 mmol/L", "Đúng 140 mmol/L"], "answer": 0, "explanation": "Trang rối loạn Na⁺ dùng ngưỡng dưới 135 mmol/L."}, {"id": "s08-q024", "page": 49, "prompt": "Theo slide, tăng K⁺ máu là khi nào?", "options": ["Trên 5,0 mmol/L", "Dưới 3,5 mmol/L", "Đúng 2,0 mmol/L", "Dưới 1,0 mmol/L"], "answer": 0, "explanation": "Slide ghi tăng K⁺ máu trên 5,0 mmol/L."}, {"id": "s08-q025", "page": 50, "prompt": "Tăng hormon PTH được liên hệ với thay đổi calcium nào?", "options": ["Tăng Ca máu", "Luôn giảm Ca máu", "Không ảnh hưởng Ca", "Biến toàn bộ Ca thành Na"], "answer": 0, "explanation": "Slide liên hệ cường cận giáp, tăng PTH với tăng Ca máu."}, {"id": "s08-q026", "page": 54, "prompt": "Sản phẩm hiện màu của phép phân tích triglyceride được nêu có màu gì?", "options": ["Hồng", "Tím đậm", "Đen", "Không màu trong mọi trường hợp"], "answer": 0, "explanation": "Slide ghi màu hồng, hấp thụ ở 492–550 nm."}, {"id": "s08-q027", "page": 55, "prompt": "Phép phân tích cholesterol toàn phần trong slide đo ở bước sóng nào?", "options": ["500 nm", "280 nm", "340 nm", "595 nm"], "answer": 0, "explanation": "Trang 55 nêu đo ở 500 nm."}, {"id": "s08-q028", "page": 56, "prompt": "Trước khi đo HDL-C, chất nào được dùng để kết tủa các lipoprotein còn lại?", "options": ["Phosphotungstic acid và Mg²⁺", "Chỉ nước cất", "Ninhydrin", "Urease và cơ chất ure"], "answer": 0, "explanation": "Slide yêu cầu kết tủa rồi ly tâm, thu phần HDL để đo cholesterol."}], "source": {"file": "6. Nước - khoáng.pdf", "url": "sources/s08.pdf", "pages": 56, "sha256": "da8a6950769da528e59f00ff8f3c3aae2525e923af677ea7d67ad47776e4c18b"}}, {"id": "s09", "title": "Khí máu và cân bằng axit–base", "group": "Khí máu", "description": "Vận chuyển O₂, CO₂; hệ đệm và các rối loạn axit–base.", "sections": [{"title": "Vận chuyển khí", "from": 3, "to": 10, "points": ["Hemoglobin là chất mang oxy trong máu; slide so sánh khả năng vận chuyển của máu chứa Hb với oxy hòa tan trong huyết tương.", "2,3-DPG làm giảm ái lực Hb với oxy.", "CO₂ được vận chuyển dưới dạng bicarbonate, carbamin và dạng hòa tan; bicarbonate là dạng chủ yếu theo slide."]}, {"title": "Hệ đệm và điều hòa", "from": 11, "to": 17, "points": ["Slide nêu pH động mạch bình thường 7,38–7,42.", "Các hệ đệm gồm bicarbonate, phosphate, protein và hệ hemoglobin trong hồng cầu.", "Điều hòa gồm đáp ứng của các hệ đệm hóa học và cơ chế sinh lý ở phổi, thận.", "Khi pH giảm, phổi tăng thông khí để thải CO₂; thận tham gia muộn hơn, tái hấp thu bicarbonate và bài tiết H⁺."]}, {"title": "Chỉ tiêu và rối loạn", "from": 18, "to": 25, "points": ["Slide dùng ngưỡng pH < 7,35 cho nhiễm acid và pH > 7,45 cho nhiễm kiềm.", "Phân biệt bicarbonate thực (AB), bicarbonate chuẩn (SB), base đệm (BB) và base dư (BE).", "Nhiễm acid chuyển hóa liên quan tích tụ acid hoặc mất base; acid hô hấp liên quan giảm thông khí, tăng CO₂.", "Nhiễm kiềm chuyển hóa liên quan mất acid hoặc dư base; kiềm hô hấp liên quan tăng thông khí quá mức và giảm CO₂.", "Các câu hỏi tập trung vào cơ chế và dấu hiệu nêu rõ trong bài, kèm liên kết đến trang PDF."]}], "questions": [{"id": "s09-q001", "page": 3, "prompt": "Chất mang oxy trong máu được nêu trong slide là gì?", "options": ["Hemoglobin", "Albumin", "Transferrin", "Ceruloplasmin"], "answer": 0, "explanation": "Slide xác định hemoglobin là chất mang oxy trong máu."}, {"id": "s09-q002", "page": 3, "prompt": "2,3-DPG có ảnh hưởng nào lên Hb theo slide?", "options": ["Giảm ái lực Hb với oxy", "Tăng ái lực Hb với oxy", "Biến Hb thành glucose", "Không thể tương tác với vận chuyển oxy"], "answer": 0, "explanation": "Slide nêu 2,3-DPG làm giảm ái lực giữa Hb và O₂."}, {"id": "s09-q003", "page": 8, "prompt": "Dạng vận chuyển CO₂ chủ yếu được nêu trong slide là gì?", "options": ["Bicarbonate", "CO₂ hòa tan tự do", "Dạng carbamin", "Oxyhemoglobin"], "answer": 0, "explanation": "Slide ghi bicarbonate chiếm tỷ lệ lớn nhất trong các dạng vận chuyển CO₂."}, {"id": "s09-q004", "page": 8, "prompt": "Dạng carbamin hình thành do CO₂ phản ứng với thành phần nào?", "options": ["Nhóm amin tự do của các chuỗi protein trong Hb", "Chỉ lipid của huyết tương", "Chỉ nhóm phosphate của ATP", "Chỉ ion natri"], "answer": 0, "explanation": "Phần mô tả carbamin nêu phản ứng với nhóm amin tự do."}, {"id": "s09-q005", "page": 11, "prompt": "Khoảng pH động mạch bình thường được nêu trong bài là bao nhiêu?", "options": ["7,38–7,42", "6,80–7,00", "7,80–8,00", "5,50–6,00"], "answer": 0, "explanation": "Bộ slide dùng khoảng 7,38–7,42 cho phần cân bằng acid–base."}, {"id": "s09-q006", "page": 12, "prompt": "Hệ đệm nào được nêu trong hồng cầu?", "options": ["Hemoglobinat/hemoglobin", "Chỉ acetate/acetic acid", "Chỉ borat/boric acid", "Chỉ glucose/glycogen"], "answer": 0, "explanation": "Slide liệt kê hệ hemoglobin và oxyhemoglobin trong hồng cầu."}, {"id": "s09-q007", "page": 13, "prompt": "Cặp thành phần của hệ đệm bicarbonate là gì?", "options": ["HCO₃⁻/H₂CO₃", "Na⁺/K⁺", "Glucose/fructose", "Albumin/cholesterol"], "answer": 0, "explanation": "Hệ đệm bicarbonate được biểu diễn bằng HCO₃⁻ và H₂CO₃."}, {"id": "s09-q008", "page": 14, "prompt": "Hai cơ quan tham gia cơ chế sinh lý điều hòa acid–base là gì?", "options": ["Phổi và thận", "Chỉ da và xương", "Chỉ gan và lách", "Chỉ cơ và tụy"], "answer": 0, "explanation": "Giai đoạn điều hòa sinh lý trong slide gồm hô hấp ở phổi và bài tiết ở thận."}, {"id": "s09-q009", "page": 15, "prompt": "Trong hệ đệm bicarbonate, H⁺ tăng phản ứng trước hết với chất nào?", "options": ["HCO₃⁻", "O₂", "Cholesterol", "Glucose"], "answer": 0, "explanation": "Slide mô tả H⁺ + HCO₃⁻ tạo H₂CO₃, rồi thành CO₂ và nước."}, {"id": "s09-q010", "page": 16, "prompt": "Khi pH giảm, đáp ứng của phổi được mô tả như thế nào?", "options": ["Tăng thông khí để thải CO₂", "Giảm thông khí để giữ CO₂", "Ngừng trao đổi khí hoàn toàn", "Tăng tạo ure"], "answer": 0, "explanation": "Slide liên hệ giảm pH với tăng thông khí và thải CO₂."}, {"id": "s09-q011", "page": 16, "prompt": "So với đáp ứng của phổi, thận tham gia điều hòa thế nào?", "options": ["Muộn hơn nhưng khả năng đệm lớn", "Luôn sớm hơn và không có khả năng đệm", "Không tham gia", "Chỉ tác động lên oxy"], "answer": 0, "explanation": "Slide nêu thận tham gia muộn hơn và có khả năng đệm lớn."}, {"id": "s09-q012", "page": 17, "prompt": "Cơ chế nào thuộc điều hòa acid–base ở thận theo slide?", "options": ["Tái hấp thu bicarbonate", "Chỉ tạo hemoglobin", "Chỉ phân giải tinh bột", "Chỉ vận chuyển oxy"], "answer": 0, "explanation": "Thận còn đào thải acid không bay hơi và bài tiết H⁺ dưới dạng muối amoni."}, {"id": "s09-q013", "page": 18, "prompt": "Theo ngưỡng trong slide, pH máu nào được xếp là nhiễm acid?", "options": ["Dưới 7,35", "Trên 7,45", "Đúng 7,40", "7,38–7,42"], "answer": 0, "explanation": "Trang chỉ tiêu nêu pH < 7,35 là nhiễm acid."}, {"id": "s09-q014", "page": 18, "prompt": "Bicarbonate chuẩn được xác định sau khi đưa mẫu về điều kiện nào?", "options": ["37 °C và PCO₂ 40 mmHg", "0 °C và PCO₂ bằng không", "100 °C và áp suất bất kỳ", "Nhiệt độ phòng, không cần kiểm soát PCO₂"], "answer": 0, "explanation": "Slide định nghĩa SB ở nhiệt độ 37 °C, PCO₂ 40 mmHg."}, {"id": "s09-q015", "page": 19, "prompt": "Base đệm BB là đại lượng nào?", "options": ["Tổng lượng anion đệm trong máu", "Tổng lượng oxy trong phổi", "Tổng lipid huyết thanh", "Chỉ nồng độ natri"], "answer": 0, "explanation": "Slide định nghĩa BB bằng tổng lượng các anion có vai trò đệm."}, {"id": "s09-q016", "page": 19, "prompt": "Giá trị BE bình thường được nêu trong slide là bao nhiêu?", "options": ["0", "10", "25", "100"], "answer": 0, "explanation": "Trang base dư nêu BE bình thường bằng 0."}, {"id": "s09-q017", "page": 20, "prompt": "Cơ chế nào được nêu có thể gây nhiễm acid chuyển hóa?", "options": ["Tích tụ acid hoặc mất bicarbonate", "Chỉ tăng thông khí quá mức", "Chỉ mất acid dạ dày", "Chỉ dư base trong máu"], "answer": 0, "explanation": "Trang acid chuyển hóa nêu tích tụ acid, mất base, giảm bài tiết H⁺ hoặc mất HCO₃⁻."}, {"id": "s09-q018", "page": 22, "prompt": "Nhiễm acid hô hấp được mô tả bằng thay đổi nào?", "options": ["Giảm thông khí, CO₂ tăng, pH giảm", "Tăng thông khí, CO₂ giảm, pH tăng", "Mất acid, pH tăng", "Dư base, pH không đổi"], "answer": 0, "explanation": "Slide liên hệ giảm thông khí với tăng CO₂ và nhiễm acid hô hấp."}, {"id": "s09-q019", "page": 23, "prompt": "Nguyên nhân nào được nêu cho nhiễm kiềm chuyển hóa?", "options": ["Nôn nhiều hoặc hút dịch dạ dày", "Giảm thông khí làm giữ CO₂", "Tích tụ acid lactic", "Mất bicarbonate do tiêu chảy"], "answer": 0, "explanation": "Mất acid dạ dày nằm trong các nguyên nhân của kiềm chuyển hóa được nêu."}, {"id": "s09-q020", "page": 25, "prompt": "Nhiễm kiềm hô hấp liên quan cơ chế nào?", "options": ["Tăng thông khí quá mức làm giảm CO₂", "Giảm thông khí làm tăng CO₂", "Tăng acid không bay hơi", "Mất bicarbonate trong mọi trường hợp"], "answer": 0, "explanation": "Slide mô tả CO₂ giảm và pH tăng khi thông khí phế nang quá mức."}], "source": {"file": "7. Vận chuyển khí trong máu và cân bằng axit base.pdf", "url": "sources/s09.pdf", "pages": 26, "sha256": "7ca7f86ebe0bc22947a02528a77cf49d18730c986ba43350de1f7a8bba2bd5d5"}}], "version": "9c6458474827"};
